import {readFileSync} from 'node:fs';
const curriculum=JSON.parse(readFileSync(new URL('../blueprint/curriculum.json',import.meta.url),'utf8'));
const B=(en,zh)=>({en,zh});
const sources={
 algebra:{title:'OpenStax — Algebra and Trigonometry',url:'https://openstax.org/books/algebra-and-trigonometry-2e/pages/preface'},
 calculus:{title:'OpenStax — Calculus',url:'https://openstax.org/books/calculus-volume-1/pages/preface'},
 linear:{title:'MIT — Linear Algebra',url:'https://ocw.mit.edu/courses/18-06-linear-algebra-spring-2010/'},
 discrete:{title:'MIT — Mathematics for Computer Science',url:'https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-spring-2015/'},
 abstract:{title:'MIT — Algebra I',url:'https://ocw.mit.edu/courses/18-701-algebra-i-fall-2010/'},
 analysis:{title:'MIT — Real Analysis',url:'https://ocw.mit.edu/courses/18-100a-real-analysis-fall-2020/'},
 geometry:{title:'MIT — Differential Geometry',url:'https://ocw.mit.edu/courses/18-950-differential-geometry-fall-2008/'},
 units:{title:'BIPM — SI Brochure',url:'https://www.bipm.org/en/publications/si-brochure'},
 stats:{title:'OpenStax — Introductory Statistics',url:'https://openstax.org/books/introductory-statistics-2e/pages/preface'}
};
export const lessons=[];
export const outlines={};
export const titles={};
const N=(en,zh,a,ex,exzh)=>[en,zh,a,'Identify the quantities and apply the stated rule step by step.','明确各量，逐步使用本节规则。',ex,exzh];
const frameworks={};
// Source content is original, with mathematical-reference links and editorial review pending.
function F(course,en,zh,source='algebra'){frameworks[course]={body:[en,zh],source};}
function D(id,zh,terms,def,ex,trap,q1,q2){const f=frameworks[id.split('.')[0]];add(id,zh,terms,def,f.body,ex,trap,q1,q2,f.source);}
const starts={F01:[],F02:['module.F01.04'],F03:['module.F01.05'],F04:[],M01:['module.F01.06'],M02:['module.M01.02'],M03:['module.F02.02'],M04:['module.M01.02'],M05:['module.M01.03','module.M02.02'],M06:['module.M01.01'],M07:['module.M01.05','module.M06.06'],M08:['module.M07.06'],M09:['module.M04.03'],M10:['module.M09.06'],M11:['module.M08.02','module.M09.04'],M12:['module.M08.03'],M13:['module.M08.06','module.F02.06'],M14:['module.F02.06'],M15:['module.M14.06','module.M09.06'],M16:['module.F02.06'],M17:['module.F02.04'],M18:['module.M17.04'],M19:['module.M17.03'],M20:['module.M19.06','module.M08.04'],M21:['module.M01.01'],M22:['module.M16.06','module.M17.06','module.M03.06','module.M21.06'],M23:['module.M05.02','module.M11.06','module.M13.05'],M24:['module.M13.06'],M25:['module.M11.06'],M26:['module.M09.06','module.M07.06']};
function add(id,zh,concepts,definition,mechanism,example,trap,q1,q2,source='algebra'){
 const courseId=id.split('.')[0], mod=curriculum.courses.find(c=>c.id===courseId).modules.find(m=>m.id===id);
 const pair=x=>B(x[0],x[1]);
 const exercises=[q1,q2].map((q,i)=>({id:`module.${id}.${i+1}`,type:'numeric',prompt:pair(q),answer:q[2],tolerance:1e-8,hints:[B(q[3],q[4])],explanation:B(q[5],q[6])}));
 const num=Number(id.split('.')[1]);
 const prerequisite=num===1?(starts[courseId]||[]):[`module.${courseId}.${String(num-1).padStart(2,'0')}`];
 const title=B(mod.title.en,zh);titles[id]=title;
 const cs=concepts.map(pair);
 outlines[id]={concepts:cs,check:B(q1[0],q1[1])};
 lessons.push({id:`module.${id}`,courseId,moduleId:id,title,summary:pair(definition),prerequisites:prerequisite,minutes:25,objectives:[B(`Explain ${concepts[0][0]} and its conditions.`,`解释${concepts[0][1]}及其适用条件。`),B(`Use ${concepts[1][0]} in a worked solution.`,`在解题中使用${concepts[1][1]}。`)],sections:[{type:'concept',title:B('Definitions and notation','定义与记号'),body:pair(definition)},{type:'concept',title:B('Why the method works','方法为什么成立'),body:pair(mechanism)},{type:'example',title:B('A worked example','逐步例题'),body:pair(example)},{type:'pitfall',title:B('Conditions and common mistakes','条件与常见错误'),body:pair(trap)}],exercises,sources:[sources[source]],visual:null,contentStatus:'original-module-first-pass',editorialReview:'pending',coverageNote:B('Core module lesson; further proof problems, transfer practice, and independent subject review remain part of curriculum development.','本课讲授模块核心内容；拓展证明、迁移练习与独立学科审校仍需继续完善。')});
}

add('F01.01','数、分数与比',[['place value','位值'],['equivalent fractions','等值分数'],['unit rate','单位比率']],
['A whole number counts objects. In base ten, each place is ten times the place to its right. A fraction a/b means a copies of one b-th of a whole, with b nonzero. A ratio compares two quantities in a stated order.','整数用来计数；十进制中，每一位的值是右边一位的十倍。分数 a/b 表示 a 个“整体的 b 分之一”，b 不能为零。比按照指定顺序比较两个量。'],
['Multiplying both numerator and denominator by the same nonzero number preserves a fraction because it multiplies by one. Addition requires equal-sized parts: convert to a common denominator first. A unit rate divides the first quantity by the second; its units explain what the result measures.','分子分母同乘一个非零数相当于乘一，因此数值不变。分数相加必须先把份的大小统一，也就是通分。单位比率用前一个量除以后一个量，结果的单位说明它衡量什么。'],
['To add 1/2 and 1/3, split the whole into sixths: 1/2 = 3/6 and 1/3 = 2/6, so the sum is 5/6. If three notebooks cost 12 yuan, the unit price is 12/3 = 4 yuan per notebook. Five such notebooks therefore cost 20 yuan.','计算 1/2 + 1/3 时，把整体分成六份：分别为 3/6 和 2/6，和为 5/6。三本笔记本共 12 元，每本价格为 12÷3=4 元；五本就是 20 元。'],
['Do not add denominators: 1/2 + 1/2 is one whole, not 2/4. A ratio depends on order: distance/time is speed, while time/distance is not speed. Always name the whole for a fraction; half of a large cake need not equal half of a small cake.','不能把分母直接相加：两个二分之一合成一整个，而不是四分之二。距离除以时间是速度，反过来不是。分数必须说明所指整体，大蛋糕的一半不一定等于小蛋糕的一半。'],
['What is 3/4 + 1/8?','3/4 + 1/8 等于多少？',0.875,'Use eighths.','通分为八分之一。','3/4 = 6/8, so the sum is 7/8.','3/4=6/8，和为7/8。'],['Six items cost 42 yuan. What is the unit price?','六件物品共42元，单价多少元？',7,'Divide cost by count.','总价除以数量。','42/6 = 7 yuan per item.','42÷6=7元/件。']);
add('F01.02','代数记号与表达式',[['variable','变量'],['expression','表达式'],['distributive law','分配律']],
['A variable is a symbol whose value can vary or is temporarily unknown. An expression describes a value; an equation asserts that two expressions have equal values. In 3x + 2, x is a variable, 3 its coefficient, and 2 a constant term.','变量是值可以变化或暂时未知的符号。表达式表示数值；等式断言两个表达式的值相等。3x+2中，x是变量，3是系数，2是常数项。'],
['The distributive law a(b+c)=ab+ac follows by combining equal groups. Parentheses determine what is grouped. Substitute by replacing every occurrence of a variable consistently, then perform powers, multiplication and division, and finally addition and subtraction.','分配律a(b+c)=ab+ac来自等量分组。括号规定分组方式。代入时，同一变量的每次出现都要一致替换，再依次计算乘方、乘除、加减。'],
['If x=4, then 2(x+3)=2×7=14. Expanding first gives 2x+6=8+6=14, the same result. To simplify 3x+2x+5, combine coefficients of the same variable: (3+2)x+5=5x+5.','x=4时，2(x+3)=2×7=14；先展开则得到2x+6=8+6=14。化简3x+2x+5时，只合并同类项，得到5x+5。'],
['An equals sign is a claim of equality, not an instruction meaning “and then.” The terms x and x² are not like terms. Write parentheses around negative substitutions: x² at x=−3 is (−3)²=9, whereas −3² conventionally means −9.','等号表示相等，不表示“然后”。x与x²不是同类项。代入负数应加括号：x=−3时，x²=(−3)²=9，而−3²通常表示−9。'],
['Evaluate 4x−1 at x=3.','x=3时，4x−1等于多少？',11,'Replace x by 3.','把x换成3。','4×3−1=11.','4×3−1=11。'],['What is the coefficient of x in 2(x+1)+3x?','2(x+1)+3x中x的系数是多少？',5,'Expand before combining.','先展开再合并。','2x+2+3x=5x+2.','2x+2+3x=5x+2。']);
add('F01.03','集合、函数与映射',[['membership','属于关系'],['domain and codomain','定义域与陪域'],['image and preimage','像与原像']],
['A set is a collection with definite membership; order and repetition do not matter. A function f:A→B assigns exactly one element of B to each element of A. A is its domain, B its codomain, and the attained outputs form its image.','集合是成员资格明确的对象集，顺序与重复不影响集合。函数f:A→B为A中每个元素指定B中唯一一个元素。A是定义域，B是陪域，实际取得的输出构成像集。'],
['Intersection keeps elements belonging to both sets; union keeps elements belonging to either. A function is injective if different inputs never share an output, and surjective if every codomain element is reached. These properties depend on the declared sets as well as the formula.','交集保留同时属于两个集合的元素，并集保留至少属于一个集合的元素。单射要求不同输入的输出不同；满射要求陪域每个元素都有原像。这些性质既取决于公式，也取决于指定的集合。'],
['For A={−1,0,1} and f(x)=x² into B={0,1,2}, the image is {0,1}. The preimage of 1 is {−1,1}. Thus f is neither injective nor surjective: two inputs collide, and 2 is missed.','A={−1,0,1}，f(x)=x²，陪域B={0,1,2}时，像集是{0,1}，1的原像是{−1,1}。它既非单射也非满射：输入有碰撞，且2未被取到。'],
['A formula alone does not always define a function on the proposed domain: 1/x has no real value at zero. An inverse function exists on the full codomain only for a bijection. Several inputs sharing one output is allowed; one input having several outputs is not.','只给公式未必能在指定定义域上定义函数：1/x在零处没有实数值。只有双射才有定义在整个陪域上的反函数。多个输入对应同一输出允许，一个输入对应多个输出则不允许。'],
['How many elements are in {1,1,2,3}?','集合{1,1,2,3}有几个元素？',3,'Repeated entries count once.','重复元素只算一次。','The set is {1,2,3}, with three elements.','该集合就是{1,2,3}，共三个元素。'],['How many real preimages does 4 have under x↦x²?','实函数x↦x²中，4有几个原像？',2,'Solve x²=4.','解x²=4。','The two preimages are −2 and 2.','原像为−2与2。'],'discrete');
add('F01.04','逻辑、量词与否定',[['implication','蕴含'],['universal quantifier','全称量词'],['existential quantifier','存在量词']],
['A proposition has a truth value. “For every x” is universal, written ∀x; “there exists x” is existential, written ∃x. The implication P⇒Q fails exactly when P is true and Q is false. It does not claim that Q causes P.','命题具有真假值。“对每个x”记为∀x，是全称量词；“存在x”记为∃x，是存在量词。P⇒Q仅在P真而Q假时为假，也不说明Q导致P。'],
['Negating a quantified statement switches its quantifier and negates its predicate. Thus not every object is red means some object is not red. Quantifier order matters: a single shared choice is stronger than allowing a different choice for each input.','否定带量词命题时，要交换量词并否定内部条件。“并非所有物体都红”就是“存在不红的物体”。量词顺序很重要：一个统一选择比为每个输入分别选择更强。'],
['Over the integers, ∀x∃y(y>x) is true: choose y=x+1. In contrast, ∃y∀x(y>x) is false because x=y already contradicts the condition. The same symbols in a different order express a different mathematical claim.','在整数中，∀x∃y(y>x)为真，可取y=x+1。∃y∀x(y>x)则为假，因为取x=y就矛盾。符号顺序不同，数学断言也不同。'],
['The converse Q⇒P need not follow from P⇒Q. “Divisible by four implies even” is true, but two is a counterexample to the converse. When negating an inequality, include equality correctly: the negation of x>3 is x≤3.','P⇒Q不能推出逆命题Q⇒P。“被4整除则为偶数”正确，但2反驳其逆命题。否定不等式要正确处理等号：x>3的否定为x≤3。'],
['Among integers 1 through 6, how many disprove “every integer here is even”?','整数1到6中，有几个反驳“这里每个整数都是偶数”？',3,'Find the odd integers.','找奇数。','1,3,5 each make the predicate false.','1、3、5都使条件为假。'],['For x=12, give y=x+1 witnessing y>x.','x=12时，按y=x+1给出满足y>x的见证。',13,'Apply the construction.','使用构造。','12+1=13, which exceeds 12.','12+1=13，大于12。'],'discrete');
add('F01.05','图像、尺度与估算',[['axis scale','坐标轴尺度'],['order of magnitude','数量级'],['interpolation','内插']],
['A graph assigns position to data using named axes and units. A linear axis uses equal distances for equal differences. A logarithmic axis uses equal distances for equal ratios. An estimate is a deliberately approximate value whose useful precision matches the information available.','图像借助带名称与单位的坐标轴把数据变成位置。线性轴以等距表示等差，对数轴以等距表示等比。估算是有意采用的近似，其精度应与已知信息匹配。'],
['Read the origin and tick spacing before comparing slopes. Slope is change in vertical quantity divided by change in horizontal quantity, so its units are a ratio. Interpolation estimates between observations; extrapolation extends beyond them and requires stronger assumptions about the pattern.','比较斜率前先读原点与刻度。斜率是纵向变化除以横向变化，因此单位是两个量的单位之比。内插估计观测之间的值；外推超出观测范围，需要更强的规律假设。'],
['A journey graph contains (2 h,120 km) and (5 h,300 km). The average rate between them is (300−120)/(5−2)=60 km/h. Estimating 198×51 as 200×50 gives about 10000, a quick scale check before exact multiplication gives 10098.','行程图含(2小时,120千米)与(5小时,300千米)，区间平均速度为180÷3=60千米/时。198×51可估为200×50≈10000，再与精确值10098核对数量级。'],
['A truncated vertical axis can visually exaggerate a difference. A straight line on logarithmic axes need not represent a linear relationship in the original quantities. Do not infer unmeasured fine detail from a coarse graph or report more significant digits than the input supports.','截断纵轴会夸大视觉差异。对数坐标上的直线未必对应原量之间的线性关系。粗略图像不能支持未测量的细节，也不能支持超过输入精度的有效数字。'],
['A quantity rises from 8 to 20 in 4 seconds. What is its average rate?','某量在4秒内从8增至20，平均变化率是多少？',3,'Use change divided by time.','变化量除以时间。','(20−8)/4=3 per second.','(20−8)/4=3每秒。'],['Estimate 49×202 by 50×200.','用50×200估算49×202。',10000,'Multiply the rounded values.','乘两个取整值。','50×200=10000.','50×200=10000。']);
add('F01.06','数学表达',[['defined symbols','符号定义'],['equivalent transformations','等价变形'],['conclusion with domain','附定义域的结论']],
['A mathematical explanation names its objects, states assumptions, connects justified steps, and identifies the conclusion. Symbols compress meaning only after their meaning is defined. An equation chain asserts that every listed expression has the same value.','数学说明要命名对象、写明假设、连接有依据的步骤并指出结论。符号只有定义后才能有效压缩意义；连等式断言其中每个表达式都相等。'],
['Separate a reason from a calculation. To solve an equation, perform reversible operations where possible and state restrictions before dividing or taking roots. A complete answer includes the permitted domain, because an algebraic candidate may be forbidden in the original problem.','应把推理依据与计算分清。解方程尽量用可逆操作，除法或开方前说明限制。完整答案包括允许的定义域，因为代数候选值可能不满足原题。'],
['Solve (x²−1)/(x−1)=3 over the reals. First exclude x=1. Factor the numerator as (x−1)(x+1), cancel only because x≠1, then obtain x+1=3 and x=2. Substituting into the original expression gives 3, confirming the admissible solution.','解(x²−1)/(x−1)=3时，先排除x=1。分解分子为(x−1)(x+1)，因x≠1才能约去，得到x+1=3，即x=2。代回原式等于3，确认解合法。'],
['Do not hide a missing argument behind “obviously.” A diagram suggests relationships but does not prove exact equality unless the assumptions guarantee it. Use = for equality, ≈ for approximation, and ⇒ for a logical consequence; these symbols have different jobs.','不要用“显然”掩盖缺失论证。图形能提示关系，却不能单独证明精确相等。等号表示相等，≈表示近似，⇒表示逻辑推出，三者作用不同。'],
['Solve (x²−4)/(x−2)=7, with x≠2.','解(x²−4)/(x−2)=7，已知x≠2。',5,'Factor x²−4.','分解平方差。','Cancel x−2 to get x+2=7, so x=5; it is allowed.','约去x−2得x+2=7，故x=5，且满足限制。'],['How many real solutions does x²=9 have?','x²=9有几个实数解？',2,'Check both signs.','检查正负两种符号。','x=3 and x=−3 both satisfy the original equation.','x=3与x=−3都满足原方程。']);

F('F02','A proof explains why a statement must hold for every object satisfying its assumptions. Start by translating the definitions into usable equations or conditions. Every inference must preserve the scope of the variables: a conveniently chosen example cannot represent an arbitrary object unless its choice was unrestricted. Search for a counterexample before investing in a proof. In a finished argument, name the assumptions, justify the transition to the conclusion, and then check boundary cases independently. Computation can suggest a theorem, but no finite list of examples proves an unrestricted claim.','证明解释为什么所有满足假设的对象都必然满足结论。先把定义翻译成可使用的方程或条件；每一步推理都必须保持变量的范围。除非对象的选择不受限制，否则一个方便的例子不能代表任意对象。投入证明前先寻找反例。完整论证应说明假设、解释如何推出结论，并独立检查边界情况。计算能够提示定理，但有限个例子不能证明无限范围的断言。','discrete');
D('F02.01','命题、定义与反例',[['definition','定义'],['universal claim','全称命题'],['counterexample','反例']],['A definition fixes meaning; a theorem needs proof. One counterexample disproves a universal claim, provided it satisfies every hypothesis.','定义规定意义，定理需要证明。反例必须满足全部假设；一个合格反例就能推翻全称命题。'],['“Every prime is odd” fails at 2: it has exactly two positive divisors, 1 and 2, yet is even. The corrected statement excludes this case.','“每个素数都是奇数”在2处失败：2恰有正因数1和2，却是偶数。修正命题须排除这个情况。'],['An example outside the assumptions is irrelevant. A definition is not proved by listing examples.','不满足假设的例子无关；列举例子也不能证明一个定义。'],N('What is the smallest even prime?','最小的偶素数是多少？',2,'Only 2 is both prime and even.','只有2既是素数又是偶数。'),N('How many positive divisors does a prime have?','素数有几个正因数？',2,'Its divisors are 1 and itself.','正因数为1与自身。'));
D('F02.02','直接证明与等价',[['direct proof','直接证明'],['biconditional','充要条件'],['two directions','两个方向']],['To prove P⇒Q, assume P and derive Q. To prove P⇔Q, establish both implications; one direction is insufficient.','证明P⇒Q要假设P并推出Q；证明P⇔Q必须完成两个方向。'],['If a=2r and b=2s are even integers, a+b=2(r+s). Because r+s is an integer, their sum is even by definition.','若a=2r、b=2s是偶数，则a+b=2(r+s)。r+s为整数，因此和按定义为偶数。'],['Do not assume the conclusion during a forward proof. Reversible algebra can prove equivalence only when all domain restrictions remain valid.','直接证明中不能预设结论；代数变形可逆且定义域条件都保留时，才能证明等价。'],N('For even numbers 14 and 22, find k with 14+22=2k.','14+22=2k，求k。',18,'The sum is 36, which is twice 18.','和为36，即2×18。'),N('How many implication directions are required for an equivalence?','证明等价需要几个蕴含方向？',2,'Prove each statement from the other.','须分别证明两边互相推出。'));
D('F02.03','逆否与反证',[['contrapositive','逆否命题'],['contradiction','矛盾'],['negated conclusion','结论的否定']],['P⇒Q is equivalent to not Q⇒not P. A contradiction proof assumes the hypotheses and the negation of the conclusion, then derives an impossibility.','P⇒Q等价于非Q⇒非P。反证法在假设下再假设结论不成立，推出矛盾。'],['To show n² odd implies n odd, prove the contrapositive: if n=2k, then n²=4k²=2(2k²) is even. This handles every even integer at once.','证明n²为奇数则n为奇数，可证逆否：若n=2k，则n²=4k²=2(2k²)为偶数，一次覆盖所有偶整数。'],['The converse and contrapositive differ. A contradiction must follow from valid steps, not from dividing by zero or making an unrelated false assertion.','逆命题不同于逆否命题；矛盾必须由合法步骤推出，不能靠除零或无关的错误断言。'],N('If n=8, what integer k satisfies n²=2k?','n=8时，n²=2k中的k是多少？',32,'64=2×32.','64=2×32。'),N('How many of 1,2,3,4 have odd squares?','1、2、3、4中有几个数的平方为奇数？',2,'Exactly the odd inputs 1 and 3.','恰为奇数输入1与3。'));
D('F02.04','数学归纳法',[['base case','基础情形'],['inductive hypothesis','归纳假设'],['inductive step','归纳步骤']],['Induction proves a statement indexed by integers: establish the first case, then show each valid case implies the next. Strong induction may use all preceding cases.','归纳法证明整数编号的命题：先证起点，再证当前成立能够推出下一项。强归纳法可使用所有之前的情况。'],['For 1+…+n=n(n+1)/2, the case n=1 holds. Assuming the formula at k, add k+1: k(k+1)/2+(k+1)=(k+1)(k+2)/2.','证明1+…+n=n(n+1)/2：n=1成立；假设k时成立，加k+1得k(k+1)/2+(k+1)=(k+1)(k+2)/2。'],['The induction hypothesis is a temporary assumption, not the theorem for all indices. A step without a base case proves no starting instance.','归纳假设只是临时假设，不是全部命题已成立；没有起点的归纳步骤不能保证任何实例。'],N('Using the formula, find 1+…+20.','用公式计算1+…+20。',210,'20×21/2=210.','20×21÷2=210。'),N('If the statement starts at n=3, which index is the base case?','命题从n=3开始，基础情形的下标是多少？',3,'The first permitted index must be established.','应验证第一个允许的下标3。'));
D('F02.05','不变量与极值方法',[['invariant','不变量'],['monovariant','单调量'],['extremal object','极值对象']],['An invariant stays unchanged under every legal move. A monovariant changes in only one direction. An extremal argument selects a smallest or largest object to restrict what can happen.','不变量在每次合法操作下保持不变；单调量只朝一个方向变化；极值论证选择最小或最大对象来限制可能情况。'],['Changing an integer by +2 or −2 preserves its parity. Starting at 3 therefore never reaches 10. The invariant is the remainder modulo 2, not the magnitude.','每次加2或减2保持奇偶性，因此从3不可能到10。不变量是模2余数，而不是数的大小。'],['An invariant must be checked for every allowed operation. Being unable to find a path does not itself prove impossibility.','必须对每一种允许操作检查不变量；没找到路径本身并不证明不可能。'],N('Starting at 7 and repeatedly adding 4, what is the remainder modulo 4?','从7开始反复加4，模4余数是多少？',3,'Adding 4 preserves the initial remainder 3.','加4保持初始余数3。'),N('A nonnegative integer decreases by at least 1 each step from 9. What is the maximum step count?','非负整数从9开始每步至少减1，最多几步？',9,'After at most nine decreases it reaches zero.','最多减九次就到零。'));
D('F02.06','写作与检查证明',[['hypothesis audit','假设检查'],['boundary cases','边界情形'],['logical gap','逻辑缺口']],['A proof audit checks definitions, quantifiers, domains, and each implication separately. State what is being proved before introducing auxiliary objects.','检查证明要分别核对定义、量词、定义域和每个蕴含；引入辅助对象之前先说明目标。'],['The argument x²=x, divide by x, hence x=1 loses x=0. Repair it by factoring x(x−1)=0 and using the zero-product property, obtaining both 0 and 1.','x²=x直接除以x得到x=1会漏掉x=0。修复方法是分解为x(x−1)=0，利用零乘积性质得到0与1。'],['A correct final answer cannot repair an invalid inference. For numerical evidence, distinguish an observed pattern from a universally established result.','正确答案不能修复非法推理；数值证据中，要区分观察到的规律与已证明的普遍结论。'],N('How many real solutions satisfy x²=4x?','x²=4x有几个实数解？',2,'x(x−4)=0 gives 0 and 4.','x(x−4)=0，解为0与4。'),N('What solution is lost by dividing x²=4x by x?','x²=4x直接除以x会漏掉哪个解？',0,'Division excludes zero, although it solves the original equation.','除法排除了零，但零满足原式。'));
F('F03','A measurement connects an observation to a defined quantity, unit, and procedure. Keep raw observations separate from processed values so another person can repeat the calculation. A model is a deliberately simplified description: name what it ignores before comparing it with data. Agreement with one observation is evidence, not a proof that the model is uniquely correct. Repeated measurements reveal some random variation; they do not automatically reveal a shared calibration error. Report the uncertainty relevant to the conclusion and investigate large residuals instead of deleting inconvenient observations.','测量把观察与明确的量、单位和过程联系起来。原始观察应与处理后的数值分开，便于复算。模型是有意简化的描述，比较数据前应说明忽略了什么。与一次观察吻合是证据，不证明模型唯一正确。重复测量能揭示部分随机波动，却不一定揭示共同的校准偏差。应报告与结论相关的不确定度，并调查较大的残差，不能随意删除不合意数据。','units');
D('F03.01','SI单位与量纲分析',[['base unit','基本单位'],['derived unit','导出单位'],['dimension','量纲']],['A unit supplies a reference size; dimension records the kind of quantity. Speed has dimension length/time and SI unit metre per second.','单位提供参照大小，量纲说明量的种类。速度的量纲是长度/时间，SI单位是米每秒。'],['Convert 72 km/h by multiplying 1000 m/km and dividing 3600 s/h: 72×1000/3600=20 m/s. Conversion factors equal one, so the physical quantity is unchanged.','72千米/时乘1000米/千米，再除3600秒/时，得到20米/秒。换算因子等于一，不改变物理量。'],['You may add only quantities of the same dimension. Dimensional consistency is necessary but cannot determine a missing numerical factor such as one half.','只有同量纲的量才能相加；量纲一致是必要条件，却不能确定二分之一之类的数值系数。'],N('Convert 36 km/h to m/s.','36千米/时等于多少米/秒？',10,'36×1000/3600=10.','36×1000÷3600=10。'),N('An area is 2 m². How many cm² is it?','2平方米等于多少平方厘米？',20000,'Each metre contributes a factor 100; square the conversion.','每个长度因子乘100，因此面积乘10000。'));
D('F03.02','测量与不确定度',[['resolution','分辨率'],['random error','随机误差'],['systematic error','系统误差']],['Resolution is the smallest distinguishable change. Random variation changes between trials; systematic error shifts results in a consistent way. Uncertainty describes a range of plausible values under stated assumptions.','分辨率是可区分的最小变化；随机波动在试验间变化，系统误差一致地偏移结果。不确定度在明确假设下描述合理值范围。'],['Measurements 9.8,10.0,10.2 mm average to 10.0 mm. Their spread does not prove the ruler is calibrated. If every reading is 0.5 mm high, averaging preserves that bias.','9.8、10.0、10.2毫米的平均值为10.0毫米；离散程度不能证明尺子校准正确。若每次都高0.5毫米，平均仍保留偏差。'],['Do not confuse accuracy with repeatability. Writing extra decimal places does not improve an instrument. Specify whether a reported uncertainty is a bound or a statistical interval.','准确不等于重复性好；多写小数位不能改善仪器。应说明不确定度是界限还是统计区间。'],N('Find the mean of 4.9,5.0,5.1.','4.9、5.0、5.1的均值是多少？',5,'Their sum is 15; divide by three.','和为15，除以3。'),N('A 20 mm reading is known to be 2 mm too high. What is the corrected value?','20毫米读数已知偏高2毫米，校正值是多少？',18,'Subtract the known positive bias.','减去已知正偏差2。'));
D('F03.03','图表与数据解释',[['scatter plot','散点图'],['slope units','斜率单位'],['association','关联']],['A scatter plot shows paired observations. Trend, spread, and outliers describe different features. Association means quantities vary together; it does not specify a causal mechanism.','散点图展示成对观察。趋势、离散与离群值描述不同特征。关联表示共同变化，不指定因果机制。'],['For time 1,2,3 s and position 2,4,6 m, the points fit position=2×time. The slope is 2 m/s. A position of 9 m at 3 s would leave a residual of 3 m.','时间1、2、3秒对应位置2、4、6米，符合位置=2×时间，斜率为2米/秒。若3秒测得9米，残差为3米。'],['Join points only when interpolation is meaningful. Bar-chart categories do not necessarily form a continuous variable, and visual correlation does not remove confounding.','只有内插有意义时才连接点；柱状图类别未必连续，视觉相关也不能排除混杂因素。'],N('Between (2 s,5 m) and (6 s,17 m), what is the slope in m/s?','(2秒,5米)到(6秒,17米)的斜率是多少米/秒？',3,'(17−5)/(6−2)=3.','(17−5)/(6−2)=3。'),N('Observed value is 11, prediction is 8. What is observed minus predicted?','观察值11，预测值8，观察减预测是多少？',3,'11−8=3.','11−8=3。'));
D('F03.04','假设、对照与混杂',[['testable hypothesis','可检验假设'],['control group','对照组'],['confounder','混杂变量']],['A hypothesis predicts an observable difference. A control provides a comparison. A confounder affects both exposure and outcome, offering an alternative explanation for association.','假设预测可观察差异；对照提供比较；混杂变量同时影响处理与结果，给关联提供其他解释。'],['To test fertilizer, randomly assign similar plants to treated and untreated groups, give equal light and water, and compare growth. Different window positions could otherwise explain a difference.','测试肥料时，把相似植物随机分到处理与未处理组，保持光照和水分一致，比较生长。不同窗位否则可能解释差异。'],['Changing several factors together prevents identifying which caused an effect. Randomization reduces systematic allocation bias; it does not guarantee identical groups in a small trial.','同时改变多个因素会妨碍辨认原因；随机分配减轻系统分配偏差，但不保证小样本两组完全相同。'],N('A trial has 24 plants equally divided into two groups. How many per group?','24株植物均分两组，每组几株？',12,'24/2=12.','24÷2=12。'),N('Treatment growth averages 8 cm; control averages 5 cm. What is the observed difference?','处理组平均长8厘米，对照组5厘米，观察差是多少？',3,'8−5=3 cm; causality still depends on design.','8−5=3厘米；因果解释仍取决于设计。'));
D('F03.05','模型、拟合与残差',[['prediction','预测'],['residual','残差'],['overfitting','过拟合']],['A fitted model chooses parameters using data. A residual equals observation minus prediction. Systematic residual patterns suggest missing structure; small training errors alone do not establish predictive reliability.','拟合模型用数据选择参数；残差等于观察减预测。系统性残差图案提示遗漏结构，训练误差小并不能保证预测可靠。'],['For y=2x+1, x=3 predicts 7. If the observation is 8, its residual is 1 and squared residual is 1. Least squares minimizes the total squared residuals over all observations.','模型y=2x+1在x=3时预测7；观测8的残差为1，平方残差为1。最小二乘使所有平方残差的总和最小。'],['A model with enough parameters may memorize noise. Check held-out data and the physical meaning of parameters; extrapolation can fail even when interpolation is excellent.','参数太多可能记住噪声；应检查留出数据与参数的物理含义。内插优秀也不保证外推有效。'],N('For y=3x+2, what is the prediction at x=4?','y=3x+2在x=4时预测多少？',14,'3×4+2=14.','3×4+2=14。'),N('Residuals are −2,1,2. What is their squared sum?','残差为−2、1、2，平方和是多少？',9,'4+1+4=9.','4+1+4=9。'));
D('F03.06','可复现的实验记录',[['raw data','原始数据'],['provenance','来源记录'],['reproducible procedure','可复现流程']],['A laboratory record preserves date, apparatus, settings, units, raw observations, transformations, and unexpected events. Reproducibility requires enough detail for another person to repeat the analysis.','实验记录保存日期、设备、设置、单位、原始观察、处理过程和异常事件；可复现要求他人能据此重复分析。'],['Record masses 12.1,12.3,12.2 g before storing their mean 12.2 g. Keep the calculation and any calibration correction alongside them, rather than replacing the originals with rounded averages.','先记录12.1、12.3、12.2克，再保存均值12.2克；把计算与校准修正附在旁边，不要用四舍五入的平均值替换原记录。'],['An unexplained deleted outlier breaks the evidence trail. Keep exclusions with reasons, distinguish observations from interpretations, and label illustrative or simulated data explicitly.','无解释地删除离群值会破坏证据链；排除值须保留理由，观察与解释分开，模拟或示意数据须明确标注。'],N('Find the mean of 12.1,12.3,12.2 g.','12.1、12.3、12.2克的均值是多少？',12.2,'The sum 36.6 divided by three is 12.2.','36.6÷3=12.2。'),N('A record has 5 trials and excludes 1 with a documented reason. How many remain?','5次试验中有1次记录原因后排除，剩几次？',4,'Five minus one leaves four; preserve all raw records.','5−1=4，仍应保留全部原始记录。'));
F('F04','Learning is stronger when you can reconstruct an idea without seeing the explanation and then use it in a changed situation. First identify the concept, its conditions, and a representative example. Close the source and explain why each step works; reopen it to correct omissions. Keep the distinction between recognition and independent performance explicit. Schedule later attempts and mix related problem types after their individual methods are understood. A useful record captures what changed in your reasoning, rather than merely how long you studied or how familiar a page looked.','能够不看说明重建概念，并在改变的情境中使用它，才表明理解更稳固。先找出概念、适用条件和代表例子，再合上材料解释每一步的理由，最后核对遗漏。应区分看懂与独立完成。理解各方法后，安排延迟练习并混合相关题型。记录应捕捉推理发生了什么改变，而不只是学习时长或页面熟悉程度。','discrete');
D('F04.01','提取练习与自我解释',[['retrieval','提取'],['self-explanation','自我解释'],['delayed check','延迟检查']],['Retrieval means producing an answer from memory before consulting it. Self-explanation asks why a step is valid and how it connects to prior ideas.','提取是查答案之前从记忆生成答案；自我解释追问步骤为什么成立以及与旧知识如何联系。'],['After studying fraction addition, cover the example and solve 1/3+1/6. Explain that common sixths permit adding counts: 2/6+1/6=3/6=1/2.','学习分数加法后盖住例题，计算1/3+1/6，并解释通分为六分之一后才能相加：2/6+1/6=1/2。'],['Immediate recognition can feel easier than retrieval while revealing less about independent recall. Correct errors after attempting, not after repeatedly copying the answer.','立即认出答案可能比提取容易，却较少揭示独立回忆能力。应先尝试再纠错，不是反复照抄答案。'],N('Reconstruct 1/3+1/6 without the example.','不看例题重建1/3+1/6。',0.5,'2/6+1/6=3/6=1/2.','2/6+1/6=3/6=1/2。'),N('A learner independently answers 7 of 10 prompts. How many need another attempt?','10个提示独立答对7个，几个需要再练？',3,'10−7=3, while correct items still benefit from later review.','10−7=3，正确项之后也宜复习。'));
D('F04.02','例题与刻意练习',[['worked example','例题'],['faded support','逐步撤除支架'],['transfer','迁移']],['A worked example makes decisions visible. Fading support means completing increasingly larger missing portions until the whole solution can be produced independently.','例题展示决策过程；逐步撤除支架是让学习者填补越来越多步骤，直到独立完成。'],['For 3x+2=14, an example subtracts 2 then divides by 3, giving x=4. Next solve 5x+3=18 with only the first hint, then explain both operations unaided.','3x+2=14的例题先减2再除3，得x=4。随后仅给首步提示解5x+3=18，再无提示解释两步。'],['Repeating a memorized surface pattern can hide missing understanding. Change numbers, representations, and which quantity is unknown while preserving the underlying principle.','重复熟记的表面形式可能掩盖理解缺失；应改变数值、表示方式和未知量，但保留底层原理。'],N('Solve 5x+3=18.','解5x+3=18。',3,'Subtract 3 to obtain 5x=15, then divide by 5.','减3得5x=15，再除5。'),N('Solve 4x−7=13.','解4x−7=13。',5,'Add 7, then divide 20 by 4.','先加7，再将20除4。'));
D('F04.03','错题记录与复习',[['error category','错误类别'],['repair','修复'],['retest','重测']],['An error log records the original reasoning, its first invalid step, the corrected principle, and a fresh test. Categorize conceptual, algebraic, reading, and checking errors separately.','错题记录包括原推理、第一个错误步骤、修正原则和新测题；概念、计算、读题与检查错误应分开。'],['If −2x<6 was changed to x<−3, the failure is not dividing correctly: division by a negative reverses order. The repair is x>−3; test x=0 in the original inequality.','若−2x<6被改为x<−3，错误在负数除法要反向。正确为x>−3；取x=0代原式即可检验。'],['An error log is useful only if revisited with new attempts. Copying a polished solution does not show that the original misconception has changed.','错题本需通过新尝试反复检查才有用；抄写漂亮答案不能表明旧误解已改变。'],N('What boundary value solves −2x=6?','−2x=6的边界值是多少？',-3,'Divide both sides by −2.','两边除以−2。'),N('Three of 8 errors were conceptual; how many were other types?','8个错误中3个为概念错误，其他类几个？',5,'8−3=5; categories guide the repair strategy.','8−3=5；分类帮助选择修复方法。'));
D('F04.04','阅读科学文本',[['claim','断言'],['evidence','证据'],['assumption','假设']],['Read a technical paragraph by identifying what is defined, what is asserted, what supports it, and under which assumptions it holds. Translate notation into a sentence.','读技术段落时，区分定义、断言、证据及成立假设，并把符号翻译成句子。'],['The formula d=vt applies to constant speed along a path when d is distance. If speed varies, one fixed v must be an appropriate average, or the distance requires accumulation over time.','d=vt在v为恒定速率、d为路程时适用。速率变化时，v须为恰当平均值，或者需要沿时间累积路程。'],['A familiar formula can have unfamiliar assumptions. Mark undefined terms and resolve them before treating a passage as understood.','熟悉公式也可能带有陌生假设；应标记未定义术语并解决，而不是把认得符号当作理解。'],N('At constant speed 3 m/s for 7 s, what distance is traveled?','以3米/秒匀速运动7秒，路程多少米？',21,'d=vt=3×7=21 m.','d=vt=3×7=21米。'),N('A paragraph names 6 terms; 2 are unfamiliar. How many are already understood?','段落有6个术语，2个不熟悉，已理解几个？',4,'6−2=4, and the two gaps should be resolved.','6−2=4，剩下两个需补足。'));
D('F04.05','双语术语与记号',[['term equivalence','术语对应'],['notation convention','记号约定'],['meaning in context','语境意义']],['A bilingual glossary should connect definitions, not merely translate isolated words. A mathematical symbol may use different conventions across fields, so record its meaning in the current context.','双语词表要连接定义，不只是翻译孤立单词。符号在不同学科可能遵循不同约定，应记录当前语境中的意义。'],['“Function” corresponds to 函数: each permitted input has exactly one output. “Image” here means 像, the attained outputs, not a photograph. In f(2)=5, the parentheses denote function evaluation.','Function对应函数：每个允许输入有唯一输出。Image在此为像，即实际输出，而非照片。f(2)=5的括号表示函数求值。'],['Do not translate a technical term by its everyday sense without checking the definition. Consistent symbols matter more than matching a particular alphabet.','不可未经定义核对就采用日常含义翻译术语；符号一致性比使用某种字母更重要。'],N('For f(x)=2x+1, what does f(3) equal?','f(x)=2x+1时，f(3)是多少？',7,'Function evaluation gives 2×3+1=7.','函数求值得2×3+1=7。'),N('How many outputs may a function assign to one input?','函数对一个输入必须指定几个输出？',1,'Exactly one, by definition.','按定义恰为一个。'));
D('F04.06','规划与展示探究',[['research question','研究问题'],['method','方法'],['qualified conclusion','有限定的结论']],['An investigation plan states a focused question, measurable variables, a procedure, comparison criteria, and limitations. A presentation links the conclusion to evidence with enough detail to check the reasoning.','探究计划应有明确问题、可测变量、过程、比较标准和限制。展示应把结论与证据联系起来，使推理可检查。'],['To compare paper bridges, hold span and paper mass fixed, vary fold shape, and measure failure load over repeated trials. Report every trial and summarize the pattern before interpreting why it occurred.','比较纸桥时固定跨度和纸质量，改变折叠形状，多次测量破坏载荷。先报告各次试验并总结规律，再解释原因。'],['A neat presentation does not compensate for an uncontrolled comparison. State what the experiment cannot establish, especially when samples or tested conditions are narrow.','漂亮展示不能弥补缺乏控制的比较；样本或条件有限时，应说明实验无法确立哪些结论。'],N('Three designs tested four times each require how many trials?','三种设计各测四次，共几次？',12,'3×4=12 trials.','3×4=12次。'),N('Loads 8,10,12 have what mean?','载荷8、10、12的均值是多少？',10,'Their total 30 divided by three is 10.','总和30除3为10。'));
F('M01','Algebraic manipulation is useful because equality is preserved when the same reversible operation is applied to both sides. A function adds the idea that each allowed input has a unique output, so formulas must be read together with their domains. When solving, first identify forbidden inputs; next transform the expression; finally substitute candidates into the original condition. Factoring exposes zeros, completing the square exposes a quadratic vertex, and logarithms undo positive exponential relationships. A graph provides an independent qualitative check: intercepts, signs, turning points, and long-run behavior should agree with the algebra.','代数变形的依据是：等式两边施行相同可逆操作保持等价。函数还要求每个允许输入有唯一输出，因此公式必须连同定义域理解。解题先排除非法输入，再变形，最后代回原条件检验。分解因式揭示零点，配方揭示二次函数顶点，对数还原正的指数关系。图像提供独立的定性检查：截距、符号、转折和远处趋势都应与代数结果一致。');
D('M01.01','表达式、方程与不等式',[['solution set','解集'],['factoring','因式分解'],['order reversal','不等号反向']],['An equation asks where two expressions agree. An inequality asks where their order holds. Multiplication or division by a negative number reverses order.','方程求两个表达式相等的位置，不等式求大小关系成立的位置。乘除负数须反向。'],['Solve 2(x−1)≤6: expand or divide by 2 to get x−1≤3, then x≤4. The endpoint is included because equality was allowed.','解2(x−1)≤6，两边除2得x−1≤3，再得x≤4；允许等号，所以端点包含。'],['Squaring can add solutions and division can lose them. Record restrictions and test candidates in the original statement.','平方可能增加解，除法可能丢失解；要记录限制并代回检验。'],N('Solve 3x+4=19.','解3x+4=19。',5,'Subtract 4 then divide 15 by 3.','减4后15除3。'),N('What is the upper endpoint of 2x−3≤7?','2x−3≤7的上端点是多少？',5,'2x≤10 gives x≤5.','2x≤10得到x≤5。'));
D('M01.02','一次与二次函数',[['slope','斜率'],['vertex','顶点'],['discriminant','判别式']],['A linear function mx+b has constant rate m. A quadratic ax²+bx+c with a≠0 has vertex x=−b/(2a); b²−4ac determines its number of real roots.','一次函数mx+b的变化率恒为m。二次函数a≠0时顶点横坐标为−b/(2a)，判别式b²−4ac决定实根个数。'],['Rewrite x²−6x+5 as (x−3)²−4. Its minimum is −4 at x=3, and factoring (x−1)(x−5) gives roots 1 and 5.','x²−6x+5配方为(x−3)²−4，最小值−4在x=3取得；因式分解得根1与5。'],['The graph opens downward when a<0, so the vertex is then a maximum. A zero discriminant means one distinct repeated root.','a<0时开口向下，顶点对应最大值；判别式为零表示一个相异的重根。'],N('Find the vertex x-coordinate of x²−8x+3.','x²−8x+3的顶点横坐标是多少？',4,'−b/(2a)=8/2=4.','−b/(2a)=8/2=4。'),N('What is the slope of 5−2x?','5−2x的斜率是多少？',-2,'The coefficient of x is the slope.','x的系数就是斜率。'));
D('M01.03','多项式与有理函数',[['polynomial degree','多项式次数'],['factor theorem','因式定理'],['pole and hole','极点与空点']],['A polynomial uses nonnegative integer powers of its variable. A rational function is a quotient of polynomials where the denominator is nonzero. A factor x−r corresponds to a root r.','多项式使用变量的非负整数次幂；有理函数是多项式之比，分母不得为零。因子x−r对应根r。'],['For (x²−4)/(x−2), factoring gives x+2 only when x≠2. The graph is a line with a missing point at (2,4), not a function defined everywhere.','(x²−4)/(x−2)仅在x≠2时化为x+2；图像是在(2,4)缺一个点的直线，并非处处有定义。'],['Cancel factors, not summands. A simplified formula can hide excluded inputs; retain the original domain.','只能约去因子，不能约去加项；简化公式可能隐藏被排除输入，必须保留原定义域。'],N('Evaluate (x²−9)/(x−3) at x=5.','x=5时，(x²−9)/(x−3)是多少？',8,'Factor to x+3, allowed at 5.','分解约去得x+3，5是合法输入。'),N('What is the degree of 2x⁴−x+7?','2x⁴−x+7的次数是多少？',4,'The largest nonzero exponent is 4.','非零项最高指数为4。'));
D('M01.04','指数与对数函数',[['exponential growth','指数增长'],['logarithm','对数'],['change of base','换底']],['For a>0 and a≠1, log_a y is the exponent x satisfying a^x=y, requiring y>0. Exponential change multiplies by a fixed factor over equal input intervals.','a>0且a≠1时，log_a y是满足a^x=y的指数x，要求y>0。指数变化在等长输入区间乘固定倍数。'],['Starting with 80 cells and doubling three times gives 80×2³=640. To find how many doublings multiply a population by 8, solve 2^t=8, obtaining t=3.','80个细胞倍增三次为80×2³=640；要知道增长8倍需几次倍增，解2^t=8得t=3。'],['log(x+y) does not equal log x+log y. The product rule log(xy)=log x+log y requires positive real arguments.','log(x+y)不等于log x+log y；实数乘积法则要求真数为正。'],N('What is log₂32?','log₂32是多少？',5,'2⁵=32.','2⁵=32。'),N('100 grows by factor 1.1 twice. What is the result?','100连续两次乘1.1，结果多少？',121,'100×1.1²=121.','100×1.1²=121。'));
D('M01.05','复合与反函数',[['composition','复合'],['inverse','反函数'],['domain restriction','定义域限制']],['Composition (f∘g)(x)=f(g(x)) applies g first. An inverse reverses a bijection; its domain is the original image. Restricting a function can make it invertible.','复合(f∘g)(x)=f(g(x))先作用g。反函数逆转双射，其定义域是原像集；限制定义域可使函数可逆。'],['If f(x)=2x+3, solve y=2x+3 for x: x=(y−3)/2. Hence f⁻¹(y)=(y−3)/2 and f⁻¹(f(4))=4.','f(x)=2x+3时，由y=2x+3解出x=(y−3)/2，故反函数为(y−3)/2，复合回去恢复4。'],['Composition is generally not commutative. The symbol f⁻¹ denotes an inverse function, not the reciprocal 1/f.','复合通常不可交换；f⁻¹表示反函数，不是倒数1/f。'],N('f(x)=x+1,g(x)=3x. Find f(g(2)).','f(x)=x+1，g(x)=3x，求f(g(2))。',7,'g(2)=6, then f(6)=7.','先得g(2)=6，再得f(6)=7。'),N('For f(x)=4x−5, find f⁻¹(7).','f(x)=4x−5，求f⁻¹(7)。',3,'Solve 4x−5=7 to obtain x=3.','解4x−5=7得3。'));
D('M01.06','参数与函数建模',[['parameter','参数'],['calibration','参数确定'],['model domain','模型适用域']],['A variable describes changing input; a parameter specifies one member of a family of models. Parameters must be estimated or stated, with units and permitted ranges.','变量描述变化输入，参数指定模型族中的一个模型。参数必须给出或估计，并说明单位与范围。'],['A taxi model C(d)=b+rd uses initial fare b and per-distance rate r. Costs 11 at d=2 and 20 at d=5 imply 3r=9, so r=3 and b=5.','出租车模型C(d)=b+rd中，b是起步费，r是单位路程费。d=2价11，d=5价20，故3r=9，r=3，b=5。'],['Fitting two observations exactly does not prove linearity outside that range. Minimum fares or tiered pricing require a piecewise model.','恰好拟合两个观察不能证明范围外也线性；最低收费或阶梯价格需要分段模型。'],N('For C(d)=5+3d, find C(4).','C(d)=5+3d时，C(4)是多少？',17,'5+3×4=17.','5+3×4=17。'),N('A line through (1,4),(3,10) has what slope?','过(1,4)、(3,10)的直线斜率多少？',3,'(10−4)/(3−1)=3.','(10−4)/(3−1)=3。'));
F('M02','Trigonometry translates between angles and coordinate ratios. Draw a unit circle or a labeled triangle before choosing a formula. On the circle, an angle determines a point whose horizontal and vertical coordinates are cosine and sine, so signs come from the quadrant. Similar triangles explain why ratios depend on angle rather than triangle size. Radians measure arc length divided by radius and are the natural unit for calculus. Identities hold wherever both sides are defined; equations ask only which angles make a particular equality true. Periodicity requires considering all permitted rotations, not just one calculator output.','三角学把角与坐标比联系起来。选择公式前先画单位圆或标注三角形。单位圆上点的横纵坐标分别是余弦与正弦，符号由象限决定。相似三角形解释比值为何依角而不依大小。弧度等于弧长除半径，是微积分的自然角单位。恒等式在两边有定义处成立；方程只求特定相等关系成立的角。周期性要求考虑允许的全部转数，不能只取计算器的一个输出。');
D('M02.01','角、弧度与单位圆',[['radian','弧度'],['arc length','弧长'],['oriented angle','有向角']],['An angle θ in radians equals arc length s divided by radius r. One full turn is 2π radians, corresponding to 360 degrees.','弧度角θ等于弧长s除半径r。一周为2π弧度，也就是360度。'],['On radius 3, a 2-radian angle cuts arc length s=rθ=6. A half-turn has angle π, so its arc length is 3π.','半径3上，2弧度截得弧长s=rθ=6；半周角为π，弧长3π。'],['The formula s=rθ requires radians. Degrees cannot be inserted without converting by π/180.','s=rθ要求弧度，角度值须先乘π/180换算。'],N('Radius is 5 and angle 0.4 radians. Find arc length.','半径5，角0.4弧度，求弧长。',2,'5×0.4=2.','5×0.4=2。'),N('How many degrees are in a quarter-turn?','四分之一周有多少度？',90,'360/4=90.','360÷4=90。'));
D('M02.02','正弦、余弦与正切',[['unit-circle coordinates','单位圆坐标'],['opposite and adjacent','对边与邻边'],['tangent ratio','正切比']],['On a unit circle, (cos θ,sin θ) locates the point. Tangent is sin θ/cos θ when cosine is nonzero. In a right triangle these become side-length ratios.','单位圆点为(cos θ,sin θ)；余弦非零时tan θ=sin θ/cos θ。直角三角形中它们成为边长之比。'],['For a right triangle with legs 3 and 4 and hypotenuse 5, the angle opposite 3 has sine 3/5, cosine 4/5, and tangent 3/4.','两直角边3、4，斜边5时，3所对角的正弦为3/5，余弦4/5，正切3/4。'],['The hypotenuse is opposite the right angle. Sine and cosine remain meaningful outside acute triangles through the circle definition.','斜边正对直角；单位圆定义使正弦余弦也适用于非锐角。'],N('Find sine of the angle opposite side 5 in a 5-12-13 triangle.','5-12-13直角三角形中，5所对角的正弦多少？',5/13,'Opposite divided by hypotenuse gives 5/13.','对边除斜边为5/13。'),N('What is cos 0?','cos 0是多少？',1,'The unit-circle point is (1,0).','单位圆上对应点为(1,0)。'));
D('M02.03','恒等式与变换',[['Pythagorean identity','平方和恒等式'],['addition formula','和角公式'],['phase shift','相位平移']],['The unit circle gives sin²θ+cos²θ=1. Addition formulas express trigonometric values of a sum; for example sin(a+b)=sin a cos b+cos a sin b.','单位圆给出sin²θ+cos²θ=1；和角公式如sin(a+b)=sin a cos b+cos a sin b。'],['If an acute angle has sine 3/5, cosine is the positive square root of 1−9/25, namely 4/5. Its double-angle sine is 2(3/5)(4/5)=24/25.','锐角正弦3/5时，余弦取√(1−9/25)的正值4/5，二倍角正弦为24/25。'],['Taking a square root loses sign information; the quadrant selects the sign. In general sin(a+b) is not sin a+sin b.','开平方丢失符号信息，须由象限选择；一般sin(a+b)不等于sin a+sin b。'],N('For acute θ with sin θ=0.6, find cos θ.','锐角θ满足sin θ=0.6，求cos θ。',0.8,'√(1−0.36)=0.8.','√(1−0.36)=0.8。'),N('What is sin²θ+cos²θ?','sin²θ+cos²θ是多少？',1,'It is the unit-circle equation.','这是单位圆方程。'));
D('M02.04','三角方程',[['principal solution','主值解'],['periodic family','周期解族'],['restricted interval','限定区间']],['Solving a trigonometric equation requires a reference angle, quadrant signs, and the requested interval. Periodicity usually creates infinitely many real solutions.','解三角方程需要参考角、象限符号和指定区间；周期性通常产生无限多个实数解。'],['sin θ=1/2 on [0,2π) has θ=π/6 and 5π/6. On the entire real line, add 2kπ to each family for any integer k.','sin θ=1/2在[0,2π)上解为π/6和5π/6；全实数范围内两族各加2kπ，k为任意整数。'],['Inverse sine returns only its principal value. Dividing by a trigonometric factor can discard zeros of that factor.','反正弦只返回主值；除以三角因子会丢掉该因子为零的情况。'],N('How many solutions does sin θ=0 have on [0,2π)?','sin θ=0在[0,2π)中有几个解？',2,'The solutions are 0 and π; 2π is excluded.','解为0与π，2π不包含。'),N('How many solutions does cos θ=1 have on [0,2π)?','cos θ=1在[0,2π)中有几个解？',1,'Only θ=0 lies in the interval.','只有θ=0在区间内。'));
D('M02.05','三角形定理与应用',[['sine law','正弦定理'],['cosine law','余弦定理'],['included angle','夹角']],['For opposite sides and angles, a/sin A=b/sin B=c/sin C. The cosine law c²=a²+b²−2ab cos C uses the included angle C.','对应边角满足a/sin A=b/sin B=c/sin C；余弦定理c²=a²+b²−2ab cos C中C为夹角。'],['Sides 3 and 4 enclose a right angle, so c²=9+16−0=25 and c=5. With included angle 60 degrees, c² instead equals 25−12=13.','边3、4夹直角时，c²=9+16=25，c=5；夹60度时c²=25−12=13。'],['Two sides and a nonincluded angle may specify zero, one, or two triangles. A calculator principal angle can miss the second possibility.','两边与非夹角可能确定零、一个或两个三角形，计算器主值角可能漏掉第二种。'],N('Find the third side for perpendicular sides 6 and 8.','两垂直边长6与8，第三边多少？',10,'√(36+64)=10.','√(36+64)=10。'),N('Two sides 5 and 5 include 60 degrees. Find the third side.','两边5、5夹60度，第三边多少？',5,'c²=25+25−50×1/2=25.','c²=25+25−50×1/2=25。'));
D('M02.06','振荡与反三角函数',[['amplitude','振幅'],['period','周期'],['inverse range','反函数值域']],['In y=A sin(ωt+φ)+D, |A| is amplitude, 2π/|ω| is period for ω≠0, and D is the midline. Inverse trigonometric functions restrict domains to obtain uniqueness.','y=A sin(ωt+φ)+D中，|A|是振幅，ω≠0时周期为2π/|ω|，D是中线。反三角函数通过限制原定义域获得唯一性。'],['For y=3sin(2t)+1, values range from −2 to 4 and one cycle lasts π. The displacement 1 shifts the center without changing the amplitude.','y=3sin(2t)+1的范围为−2到4，周期π；加1只移动中心，不改变振幅。'],['Frequency and angular frequency differ by 2π. arcsin(sin θ)=θ only when θ lies in the principal interval [−π/2,π/2].','频率与角频率差2π倍；arcsin(sin θ)=θ只在主值区间[−π/2,π/2]成立。'],N('Find the maximum of 4sin t−2.','4sin t−2的最大值多少？',2,'4×1−2=2.','4×1−2=2。'),N('Find the amplitude of −7cos(3t)+5.','−7cos(3t)+5的振幅多少？',7,'Amplitude is the absolute coefficient, 7.','振幅取系数绝对值7。'));
F('M03','Euclidean geometry reasons from explicit assumptions about points, lines, distances, and angles. Congruence preserves lengths and angles; similarity preserves angles and ratios of corresponding lengths. Mark which statements come from the problem and which require proof. Auxiliary lines can create triangles with known angle or side relations, but they must be defined precisely. Area can be calculated in different ways to expose ratios. A diagram helps choose a strategy, yet apparent perpendicularity or equal length is not evidence unless justified. Degenerate configurations, such as collinear triangle vertices, must be excluded when a theorem requires a genuine triangle.','欧氏几何从点、线、距离与角的明确假设出发。全等保持长度与角，相似保持角与对应长度比。应区分题设与待证结论；辅助线可创造已知边角关系，但要精确定义。用不同方式计算面积可揭示比值。图形帮助选择策略，却不能仅凭外观看出垂直或等长。定理要求真正三角形时，应排除顶点共线等退化情形。');
D('M03.01','公理、全等与相似',[['SSS congruence','边边边全等'],['AA similarity','角角相似'],['scale factor','相似比']],['Three corresponding equal sides imply triangle congruence. Two corresponding equal angles imply similarity; lengths scale by k and areas by k².','三组对应边相等推出三角形全等；两组角相等推出相似，长度乘k，面积乘k²。'],['Triangles with sides 3,4,5 and 6,8,10 have scale factor 2. Their perimeters have ratio 2 and their areas ratio 4.','边长3、4、5与6、8、10的三角形相似比2，周长比2，面积比4。'],['Equal angles do not imply equal sizes. Match corresponding vertices consistently before forming ratios.','等角不代表大小相等；列比值前要正确匹配顶点。'],N('A similar triangle scales length by 3. What is its area factor?','相似长度扩大3倍，面积扩大几倍？',9,'Area scales as 3²=9.','面积按3²=9倍变化。'),N('A side 7 scales by 2.5. Find its corresponding length.','边长7按2.5倍放大，对应边多少？',17.5,'7×2.5=17.5.','7×2.5=17.5。'));
D('M03.02','三角形与特殊中心',[['centroid','重心'],['circumcenter','外心'],['incenter','内心']],['Medians meet at the centroid, perpendicular bisectors at the circumcenter, and angle bisectors at the incenter. Each center is defined by a different geometric condition.','中线交于重心，垂直平分线交于外心，角平分线交于内心；各中心对应不同几何条件。'],['The centroid divides every median in a 2:1 ratio measured from the vertex. A median of length 12 therefore has vertex-to-centroid length 8 and remaining length 4.','重心从顶点起按2:1分中线；中线长12时，顶点到重心长8，另一段长4。'],['The circumcenter can lie outside an obtuse triangle. The incenter is equidistant from sides, not generally from vertices.','钝角三角形外心可在外部；内心到边等距，不是通常到顶点等距。'],N('A median is 15. Find the vertex-to-centroid distance.','中线长15，顶点到重心多少？',10,'Take 2/3 of 15.','取15的2/3。'),N('An equilateral triangle has angle sum 180 degrees. Find each angle.','等边三角形角和180度，每角多少度？',60,'Equal angles divide 180 into three equal parts.','三等角均分180。'));
D('M03.03','圆与圆内接四边形',[['inscribed angle','圆周角'],['cyclic quadrilateral','圆内接四边形'],['power of a point','点的幂']],['An inscribed angle is half the central angle subtending the same arc. Opposite angles of a cyclic quadrilateral sum to 180 degrees. Intersecting chord segment products are equal.','同弧圆周角为圆心角一半；圆内接四边形对角和180度；相交弦分段乘积相等。'],['Chords through an interior point have segment lengths 3,8 and 4,x. Power of a point gives 3×8=4x, hence x=6.','两弦在圆内交，分段为3、8与4、x。由点的幂，3×8=4x，得x=6。'],['The angles must subtend the same arc. For tangent-secant power, use the whole secant length, not only its interior segment.','必须对应同一段弧；切割线定理使用整条割线段，而不只是圆内部分。'],N('A cyclic quadrilateral has one angle 73 degrees. Find its opposite angle.','圆内接四边形一个角73度，对角多少度？',107,'180−73=107.','180−73=107。'),N('A central angle is 100 degrees. Find an inscribed angle on the same arc.','同弧圆心角100度，圆周角多少度？',50,'The inscribed angle is half.','圆周角为一半。'));
D('M03.04','面积、比与几何不等式',[['shared altitude','同高'],['area ratio','面积比'],['triangle inequality','三角不等式']],['Triangle area is half base times perpendicular height. Triangles sharing an altitude have areas proportional to bases. Genuine triangle sides satisfy each side less than the sum of the other two.','三角形面积为底乘垂直高的一半；同高三角形面积比等于底比。非退化三角形任一边小于另外两边和。'],['Split a base into lengths 2 and 3 and join the division point to the opposite vertex. The two areas have ratio 2:3 because their heights agree.','把底边分为2与3并连到对顶点，两三角形同高，面积比为2:3。'],['A slanted side is not the height unless perpendicular to the base. Equality in a triangle inequality gives a degenerate straight configuration.','斜边不是高，除非垂直底边；三角不等式取等会退化成直线。'],N('Find the area of base 8 and height 5.','底8、高5的三角形面积多少？',20,'8×5/2=20.','8×5÷2=20。'),N('A total area 30 is divided in ratio 2:3. Find the smaller area.','总面积30按2:3分，小块面积多少？',12,'Two of five equal shares gives 30×2/5=12.','五份取二，30×2/5=12。'));
D('M03.05','变换与作图',[['reflection','反射'],['rotation','旋转'],['perpendicular bisector','垂直平分线']],['Translations, rotations, and reflections preserve distances. A compass-and-straightedge construction must use permitted operations and justify why the resulting point meets the requested conditions.','平移、旋转、反射保持距离。尺规作图须使用允许操作，并解释构造点为什么满足条件。'],['Equal-radius circles centered at A and B meet at P,Q. Both intersection points are equidistant from A and B, so line PQ is their perpendicular bisector.','以A、B为心作等半径圆交于P、Q，两交点到A、B等距，因此PQ为AB的垂直平分线。'],['A dilation changes distances by its scale factor, so it is generally not an isometry. A drawing alone does not establish constructibility.','位似按比例改变距离，一般不保距；画得出来并不能证明可尺规作出。'],N('Reflect (3,−2) across the y-axis. What is the new x-coordinate?','(3,−2)关于y轴反射，新x坐标多少？',-3,'Reflection changes x to −x.','反射把x变为−x。'),N('A length 4 is dilated by 3. Find the image length.','长4按3倍位似，像长多少？',12,'4×3=12.','4×3=12。'));
D('M03.06','立体几何与空间推理',[['cross-section','截面'],['surface area','表面积'],['volume scaling','体积缩放']],['A solid can be studied through cross-sections and projections. Similar solids scale area by k² and volume by k³. Perpendicularity must be checked in space, not inferred from a flat sketch.','立体可通过截面和投影研究；相似立体面积按k²、体积按k³变化。空间垂直不能只从平面草图判断。'],['A cuboid with edges 2,3,6 has volume 36 and space diagonal √(4+9+36)=7. The diagonal formula applies the Pythagorean theorem twice.','边长2、3、6的长方体体积36，体对角线√(4+9+36)=7，来自两次勾股定理。'],['Volume and surface area use different powers and units. Skew lines are neither intersecting nor parallel, a possibility absent in one plane.','体积与表面积使用不同幂次和单位；异面直线既不相交也不平行，是平面中没有的情况。'],N('A cube side is 4. Find its volume.','边长4的立方体体积多少？',64,'4³=64.','4³=64。'),N('All lengths double. What is the volume factor?','全部长度加倍，体积扩大几倍？',8,'2³=8.','2³=8。'));
F('M04','Coordinates convert geometric conditions into equations. Choose axes and an origin that simplify the objects, while remembering that distances and angles describe geometry rather than the coordinate labels themselves. A vector records displacement, so translating its starting point does not change it. Dot products turn angle and perpendicularity questions into algebra; cross products in three dimensions encode oriented area. Solve intersections by requiring the same point to satisfy both descriptions. After an algebraic calculation, reconstruct the geometry: verify dimensions, directions, and whether the calculated point lies on the intended line, segment, ray, or curve.','坐标把几何条件化为方程。应选择使对象简单的轴与原点，同时记住距离和角描述几何本身，而不依坐标标签。向量记录位移，平移起点不改变向量。点积把角与垂直问题化为代数，三维叉积编码有向面积。求交点就是让同一点同时满足两种描述。计算后须还原几何，检查量纲、方向以及点是否位于指定直线、线段、射线或曲线上。');
D('M04.01','直角坐标与距离',[['ordered coordinates','有序坐标'],['distance formula','距离公式'],['midpoint','中点']],['Coordinates are signed distances along perpendicular axes. The distance between (x₁,y₁),(x₂,y₂) is √((x₂−x₁)²+(y₂−y₁)²). The midpoint averages coordinates.','坐标为沿垂直轴的有向位置；两点距离为坐标差平方和开方，中点取各坐标平均。'],['From (−1,2) to (2,6), displacement is (3,4), giving distance 5 and midpoint (0.5,4).','从(−1,2)到(2,6)，位移为(3,4)，距离5，中点(0.5,4)。'],['Coordinates depend on the chosen frame. Subtract endpoints in a consistent order when direction matters.','坐标依参照系而定；涉及方向时，端点相减顺序须一致。'],N('Find the distance from (0,0) to (8,15).','原点到(8,15)距离多少？',17,'√(64+225)=17.','√(64+225)=17。'),N('Find the midpoint x-coordinate of (2,1),(8,9).','(2,1)、(8,9)中点的x坐标多少？',5,'(2+8)/2=5.','(2+8)/2=5。'));
D('M04.02','直线、平面与交点',[['normal vector','法向量'],['line equation','直线方程'],['simultaneous equations','联立方程']],['A line ax+by=c has normal (a,b). In space, ax+by+cz=d defines a plane when the normal is nonzero. Intersections satisfy all relevant equations.','直线ax+by=c的法向量是(a,b)；空间中非零法向量下ax+by+cz=d定义平面。交点满足全部相关方程。'],['Intersect y=2x+1 with y=−x+7: equate right sides to obtain 3x=6, so x=2 and y=5.','联立y=2x+1与y=−x+7，得3x=6，因此x=2、y=5。'],['Vertical lines have no finite slope but have a valid equation x=c. Parallel distinct lines have no intersection.','竖直线没有有限斜率，但可写x=c；相异平行线没有交点。'],N('Find x at the intersection y=x+2 and y=3x.','y=x+2与y=3x交点的x是多少？',1,'x+2=3x gives x=1.','x+2=3x得1。'),N('For plane x+2y+z=8 with x=1,y=2, find z.','平面x+2y+z=8中x=1、y=2，求z。',3,'z=8−1−4=3.','z=8−1−4=3。'));
D('M04.03','向量加法与数量积',[['linear combination','线性组合'],['dot product','点积'],['orthogonality','正交']],['Vectors add componentwise. The dot product u·v equals the sum of coordinate products and also |u||v|cos θ. Nonzero perpendicular vectors have zero dot product.','向量逐坐标相加；点积为坐标乘积之和，也等于|u||v|cos θ。非零垂直向量点积为零。'],['For u=(2,1),v=(−1,2), u·v=−2+2=0, so they are perpendicular. Their sum is (1,3), which represents consecutive displacements.','u=(2,1)、v=(−1,2)时点积−2+2=0，因此垂直；和为(1,3)，表示连续位移。'],['The dot product is a scalar, not a vector. The zero vector has zero dot product with all vectors but has no defined direction angle.','点积是标量而非向量；零向量与所有向量点积为零，但没有确定方向角。'],N('Compute (3,4)·(1,2).','计算(3,4)·(1,2)。',11,'3×1+4×2=11.','3×1+4×2=11。'),N('Find the length of (6,8).','向量(6,8)的长度多少？',10,'√(36+64)=10.','√(36+64)=10。'));
D('M04.04','圆锥曲线',[['ellipse','椭圆'],['hyperbola','双曲线'],['parabola','抛物线']],['Conics are plane sections of a cone. Standard equations reveal their symmetry: an ellipse has x²/a²+y²/b²=1, while a hyperbola changes one plus sign to minus.','圆锥曲线来自平面截圆锥；标准方程揭示对称性。椭圆为x²/a²+y²/b²=1，双曲线把一个加号改为减号。'],['For x²/25+y²/9=1, the semiaxes are 5 and 3. At x=0, y=±3; at y=0, x=±5.','x²/25+y²/9=1的半轴为5与3；x=0时y=±3，y=0时x=±5。'],['Denominators are squared semiaxes, not semiaxes themselves. A translated conic requires completing squares before identifying its center.','分母是半轴的平方；平移后的曲线应先配方再找中心。'],N('Find the horizontal semiaxis of x²/16+y²/4=1.','x²/16+y²/4=1的水平半轴多少？',4,'√16=4.','√16=4。'),N('For y=x²/4, find y at x=6.','y=x²/4中x=6，y多少？',9,'36/4=9.','36/4=9。'));
D('M04.05','参数与极坐标表示',[['parameter','参数'],['polar radius','极径'],['coordinate conversion','坐标转换']],['A parametric curve gives coordinates as functions of t. Polar coordinates use x=r cos θ,y=r sin θ, allowing a point to have multiple angle representations.','参数曲线把坐标写成t的函数；极坐标用x=r cos θ、y=r sin θ，同一点可有多个角表示。'],['x=2t+1,y=3t−2 gives (5,4) at t=2. Eliminating t gives y=1.5x−3.5, but the permitted t interval still controls which part of the line is traced.','x=2t+1、y=3t−2在t=2时为(5,4)；消参得y=1.5x−3.5，但t的范围仍决定轨迹是哪一段。'],['Eliminating a parameter can lose direction and domain information. Polar angle alone does not determine distance from the origin.','消参可能丢失方向和范围信息；只有极角不能确定距原点多远。'],N('For x=3t−1, find x at t=4.','x=3t−1，t=4时x多少？',11,'3×4−1=11.','3×4−1=11。'),N('Polar r=5,θ=0. Find x.','极坐标r=5、θ=0，x多少？',5,'x=5cos0=5.','x=5cos0=5。'));
D('M04.06','三维向量与叉积',[['cross product','叉积'],['oriented area','有向面积'],['scalar triple product','数量三重积']],['In three dimensions u×v is perpendicular to both vectors and has magnitude |u||v|sin θ. Its orientation follows the right-hand rule. A scalar triple product gives signed volume.','三维叉积u×v垂直两向量，大小为|u||v|sin θ，方向遵循右手定则；数量三重积给有向体积。'],['For u=(2,0,0),v=(0,3,0), u×v=(0,0,6). The parallelogram area is 6, while the triangle formed by those sides has area 3.','u=(2,0,0)、v=(0,3,0)的叉积为(0,0,6)；平行四边形面积6，对应三角形面积3。'],['Swapping operands reverses the cross product. Parallel vectors yield zero, so zero cannot define a unique plane normal.','交换顺序使叉积反向；平行向量叉积为零，不能用它确定唯一法向量。'],N('Find |(4,0,0)×(0,5,0)|.','求|(4,0,0)×(0,5,0)|。',20,'Perpendicular lengths multiply to 20.','垂直边长相乘为20。'),N('Find volume of the parallelepiped along axes with lengths 2,3,4.','沿三轴边长2、3、4的平行六面体体积多少？',24,'The scalar triple product is 2×3×4=24.','数量三重积为2×3×4=24。'));
function R(id,zh,te,tz,de,dz,ee,ez,pe,pz,q1,q2){const terms=te.split(';').map((s,i)=>[s,tz.split(';')[i]]);D(id,zh,terms,[de,dz],[ee,ez],[pe,pz],N(q1[0],q1[1],q1[2],q1[3]||ee,q1[4]||ez),N(q2[0],q2[1],q2[2],q2[3]||ee,q2[4]||ez));}
F('M05','Complex numbers extend the real numbers by introducing i with i²=−1. Every complex number has real and imaginary coordinates, so an algebraic expression can also describe a point or displacement in a plane. Addition combines coordinates; multiplication combines scale and angle. Polynomial identities remain algebraic statements valid at every permitted input, while root equations identify special inputs. Division, factoring, and coefficient comparison provide complementary views of the same polynomial. Keep multiplicity separate from the count of distinct roots, and distinguish a polynomial from a rational expression with excluded denominator zeros. Geometric interpretations must agree with the corresponding algebra.','复数引入满足i²=−1的i，把实数扩展为平面坐标。加法逐坐标结合，乘法同时结合缩放和转角。多项式恒等式对所有允许输入成立，根方程寻找特殊输入。除法、分解和比较系数给出互补视角。须区分重数与相异根个数，也须区分多项式与排除分母零点的有理式；几何解释应与代数一致。');
R('M05.01','复数运算与平面','real part;conjugate;modulus','实部;共轭;模','Write z=a+bi; its conjugate is a−bi and |z|=√(a²+b²).','写z=a+bi，共轭为a−bi，模为√(a²+b²)。','(2+3i)(1−i)=5+i by expansion and i²=−1. Also (3+4i)(3−4i)=25.','展开并用i²=−1，得(2+3i)(1−i)=5+i；(3+4i)(3−4i)=25。','Complex numbers have no order compatible with all ordered-field rules.','复数不能配备满足全部有序域规则的大小顺序。',['Find the real part of (2+3i)(1−i).','求(2+3i)(1−i)实部。',5],['Find |3+4i|.','求|3+4i|。',5,'The modulus is √25=5.','模为√25=5。']);
R('M05.02','极形式与单位根','argument;De Moivre;roots of unity','辐角;棣莫弗公式;单位根','Polar form z=r(cosθ+i sinθ) turns multiplication into multiplying radii and adding angles.','极形式z=r(cosθ+i sinθ)使乘法变成模相乘、角相加。','The fourth roots of 1 are 1,i,−1,−i, separated by π/2. Squaring i gives −1 and i⁴=1.','1的四次单位根为1、i、−1、−i，角相差π/2；i²=−1，i⁴=1。','Arguments differ by multiples of 2π; root extraction must include all angle branches.','辐角相差2π整数倍；开根必须包含全部角分支。',['How many fourth roots of 1 exist?','1有几个四次方根？',4],['What is i⁴?','i⁴是多少？',1]);
R('M05.03','多项式除法与分解','division algorithm;remainder;factor theorem','除法算法;余数;因式定理','For nonzero D, P=DQ+R with degree R below degree D. Dividing by x−a leaves remainder P(a).','D非零时P=DQ+R，余式次数小于D；除x−a的余数为P(a)。','x²−3x+2=(x−1)(x−2), so dividing by x−1 leaves zero remainder and quotient x−2.','x²−3x+2=(x−1)(x−2)，除x−1余数零，商为x−2。','The coefficient field matters: a polynomial may factor over complex but not real numbers.','系数域很重要：多项式可能在复数域可分解而实数域不行。',['Find the remainder of x²−3x+2 divided by x−1.','x²−3x+2除x−1余数多少？',0],['Evaluate that polynomial at x=3.','该多项式在x=3的值多少？',2,'9−9+2=2.','9−9+2=2。']);
R('M05.04','韦达关系与根结构','root sum;root product;multiplicity','根和;根积;重数','For ax²+bx+c, roots counted with multiplicity have sum −b/a and product c/a.','ax²+bx+c的根按重数计，其和为−b/a，积为c/a。','x²−7x+12=(x−3)(x−4): the roots sum to 7 and multiply to 12, matching coefficients.','x²−7x+12=(x−3)(x−4)，根和7、根积12，与系数一致。','A repeated root counts repeatedly in coefficient relations.','系数关系中重根须按重数重复计入。',['Find the sum of roots of x²−7x+12.','x²−7x+12的根和多少？',7],['Find their product.','根积多少？',12]);
R('M05.05','插值与多项式恒等式','interpolation;distinct nodes;root bound','插值;互异节点;根数界','A polynomial of degree at most n is uniquely determined by n+1 distinct input-value pairs.','次数至多n的多项式由n+1个互异输入上的值唯一确定。','The line through (0,1),(2,5) is P(x)=2x+1. If two degree-one polynomials agree at both nodes, their difference has two roots and must vanish.','过(0,1)、(2,5)的直线为2x+1；两个一次多项式若两点相同，其差有两根，必恒为零。','Repeated input nodes do not supply independent value conditions. High-degree interpolation may oscillate.','重复节点不提供独立值条件；高次插值可能振荡。',['For that interpolating line, find P(3).','该插值直线的P(3)是多少？',7,'2×3+1=7.','2×3+1=7。'],['How many distinct values determine a polynomial of degree at most 3?','至多三次多项式需几个互异节点值唯一确定？',4,'n+1=4.','n+1=4。']);
R('M05.06','复数几何','rotation;distance;perpendicularity','旋转;距离;垂直','Multiplication by a unit complex number rotates the plane. Distance between z,w is |z−w|.','乘单位复数对应平面旋转，z与w间距离为|z−w|。','Multiplying 3+4i by i gives −4+3i: a quarter-turn counterclockwise. Its modulus remains 5 because the multiplier has modulus 1.','(3+4i)i=−4+3i，是逆时针四分之一转；乘数模为1，所以模仍为5。','Translation requires addition, not multiplication; a zero multiplier collapses all points.','平移用加法不是乘法；乘零把所有点压到一点。',['After multiplying 3+4i by i, find the real coordinate.','3+4i乘i后的实坐标多少？',-4],['What is its distance from the origin?','它离原点多远？',5]);
F('M06','A sequence is a function whose inputs are integer indices. An explicit formula gives a term directly, while a recurrence relates it to earlier terms and therefore needs initial values. To justify a proposed formula, check both the initial conditions and the recurrence; matching the first few terms alone is insufficient. Summation often becomes simpler by pairing terms, subtracting shifted copies, or arranging cancellation. Generating functions encode an entire sequence as coefficients of a formal power series. Growth comparisons concern eventual behavior, so finite early terms and multiplicative constants must be distinguished from the asymptotic scale.','数列是以整数下标为输入的函数。通项直接给出项，递推联系之前各项，因此需要初值。验证公式须同时检查初值与递推，前几项吻合还不够。配对、移位相减和抵消能简化求和。生成函数把整个数列编码为形式幂级数系数。增长比较研究最终行为，须区分有限前项、常数倍与渐近尺度。');
R('M06.01','等差与等比数列','common difference;common ratio;finite sum','公差;公比;有限和','An arithmetic sequence adds fixed d; a geometric sequence multiplies fixed r. Their nth terms are a₁+(n−1)d and a₁r^(n−1).','等差每次加d，等比每次乘r；第n项分别为a₁+(n−1)d、a₁r^(n−1)。','Starting at 3 with difference 4 gives 3,7,11,15. Starting at 2 with ratio 3 gives 2,6,18,54.','首项3公差4得到3、7、11、15；首项2公比3得到2、6、18、54。','Index conventions matter: a sequence starting at index zero uses different exponents.','起始下标重要：从零编号时指数形式会改变。',['Find the fourth arithmetic term in the example.','例中等差数列第四项多少？',15],['Find the fourth geometric term.','例中等比数列第四项多少？',54]);
R('M06.02','求和与裂项','sigma notation;telescoping;partial sum','求和符号;裂项;部分和','A telescoping sum contains terms that cancel after adjacent expressions are expanded. Keep the surviving endpoints.','裂项和在展开相邻表达式后大量抵消，须保留未抵消端点。','Because 1/[k(k+1)]=1/k−1/(k+1), summing k=1 through 4 gives 1−1/5=4/5.','由1/[k(k+1)]=1/k−1/(k+1)，k从1到4求和得1−1/5=4/5。','Cancellation works across addition only after an exact decomposition, not by deleting arbitrary factors.','抵消须先作准确分解，不能随意删除因子。',['Find Σ from k=1 to 4 of 1/[k(k+1)].','求k=1到4的1/[k(k+1)]之和。',0.8],['Find the same sum through k=9.','同样求和到k=9是多少？',0.9,'The endpoints give 1−1/10=0.9.','端点给出1−1/10=0.9。']);
R('M06.03','一阶递推','initial condition;fixed point;iteration','初值;不动点;迭代','A first-order recurrence uses the previous term. For a_(n+1)=ra_n+b, subtract a fixed point L satisfying L=rL+b when r≠1.','一阶递推用前一项；a_(n+1)=ra_n+b中，r≠1时可减去满足L=rL+b的不动点。','For a_(n+1)=a_n/2+3, L=6. Starting at a₀=2 gives a₁=4,a₂=5 and a_n−6=−4/2^n.','a_(n+1)=a_n/2+3的不动点6；a₀=2时a₁=4、a₂=5，且a_n−6=−4/2^n。','A fixed point need not attract: attraction here requires |r|<1.','不动点不一定吸引，线性情形需|r|<1。',['Find the fixed point of a↦a/2+3.','a↦a/2+3的不动点多少？',6],['From a₀=2, find a₂.','a₀=2时a₂多少？',5]);
R('M06.04','线性递推与特征根','characteristic equation;repeated root;initial values','特征方程;重根;初值','Trying a_n=r^n converts a homogeneous constant-coefficient recurrence into a polynomial equation for r. Repeated roots introduce polynomial factors in n.','令a_n=r^n把常系数齐次递推化为关于r的多项式方程；重根对应n的多项式因子。','For a_n=3a_(n−1)−2a_(n−2), r²−3r+2=0 has roots 1,2. Thus a_n=A+B2^n; a₀=1,a₁=3 gives A=−1,B=2.','递推a_n=3a_(n−1)−2a_(n−2)特征根1、2；a_n=A+B2^n。初值1、3给A=−1、B=2。','The recurrence alone does not determine the coefficients; enough initial values are essential.','递推本身不确定系数，必须提供足够初值。',['With a₀=1,a₁=3, find a₂.','a₀=1、a₁=3时a₂多少？',7,'3×3−2×1=7.','3×3−2×1=7。'],['Find the larger characteristic root.','较大特征根多少？',2]);
R('M06.05','生成函数入门','formal series;coefficient extraction;convolution','形式级数;系数提取;卷积','The ordinary generating function is A(x)=Σa_nx^n. Multiplication combines coefficients by convolution, keeping every pair of indices summing to the target.','普通生成函数为A(x)=Σa_nx^n；乘法通过卷积组合系数，遍历下标和等于目标的配对。','(1+x+x²+… )² has coefficient n+1 at x^n: choose the first exponent from 0 through n. Thus the x³ coefficient is 4.','(1+x+x²+…)²中x^n系数为n+1，因为第一个指数可从0取到n；x³系数为4。','Formal manipulations concern coefficients; analytic convergence is a separate question.','形式运算关注系数，解析收敛是另一个问题。',['Find the x³ coefficient of 1/(1−x)².','1/(1−x)²的x³系数多少？',4],['Find its x⁵ coefficient.','其x⁵系数多少？',6,'The coefficient is n+1=6.','系数为n+1=6。']);
R('M06.06','界与渐近增长','big O;little o;dominant term','大O;小o;主导项','f=O(g) means |f| is eventually bounded by a constant multiple of |g|. f=o(g) means f/g tends to zero where defined.','f=O(g)表示最终|f|被|g|的常数倍控制；f=o(g)表示比值趋零。','For n≥1, 3n²+2n+1≤6n², so it is O(n²). Dividing by n² gives 3+2/n+1/n²→3.','n≥1时3n²+2n+1≤6n²，故为O(n²)；除n²得3+2/n+1/n²→3。','Big O is an upper bound, not necessarily a tight classification. It does not imply equal values.','大O是上界，不必紧确，也不表示数值相等。',['What is the limit of (3n²+2n+1)/n²?','(3n²+2n+1)/n²的极限多少？',3],['For n=1, evaluate 3n²+2n+1.','n=1时代入3n²+2n+1。',6]);
F('M07','Differential calculus studies local change by comparing nearby function values. A limit describes a value approached, not necessarily a value attained. A derivative is a limit of difference quotients and therefore requires the relevant limit to exist. Algebraic rules speed calculations only after differentiability and domains are checked. Geometrically, the derivative gives tangent slope; physically, differentiating position with respect to time gives instantaneous velocity. Use signs to study increasing and decreasing behavior, but check endpoints and nondifferentiable points separately when optimizing. A local linear approximation is accurate only over a range justified by how the derivative itself changes.','微分研究邻近函数值的局部变化。极限描述趋近值，不必等于实际取值。导数是差商极限，必须先存在。求导规则能加速计算，但要先检查可导性和定义域。几何上导数给切线斜率，物理上位置对时间求导给瞬时速度。导数符号可研究增减，优化还须检查端点和不可导点；线性近似的适用范围由导数自身变化控制。','calculus');
R('M07.01','极限与连续','limit;continuity;one-sided limit','极限;连续;单侧极限','Continuity at a means the limit as x approaches a equals f(a). Both one-sided limits must agree at an interior point.','a处连续要求x趋a时极限等于f(a)；内点两侧极限须一致。','For x≠1, (x²−1)/(x−1)=x+1, so its limit at 1 is 2 although the original expression is undefined there.','x≠1时(x²−1)/(x−1)=x+1，故在1处极限为2，虽然原式无定义。','Substituting into an undefined quotient is not evaluating a limit.','向无定义分式代入不等于求极限。',['Find lim as x→1 of (x²−1)/(x−1).','求x趋1时(x²−1)/(x−1)极限。',2],['What value fills the hole continuously?','补上哪个函数值可使它连续？',2]);
R('M07.02','导数作为局部变化率','difference quotient;instantaneous rate;tangent','差商;瞬时变化率;切线','f′(a)=lim[h→0](f(a+h)−f(a))/h. The quotient is an average rate before taking the limit.','f′(a)=lim[h→0](f(a+h)−f(a))/h；取极限前商是平均变化率。','For f(x)=x², the quotient is (2ah+h²)/h=2a+h, so f′(a)=2a. At a=3 the tangent slope is 6.','f(x)=x²的差商为2a+h，极限2a；a=3时切线斜率6。','A sharp corner can have unequal one-sided slopes even when the function is continuous.','尖角即使连续，也可能左右斜率不同而不可导。',['Find the derivative of x² at x=3.','x²在x=3处导数多少？',6],['Find it at x=−2.','x=−2处呢？',-4,'2(−2)=−4.','2(−2)=−4。']);
R('M07.03','求导法则','product rule;quotient rule;chain rule','乘积法则;商法则;链式法则','The chain rule differentiates f(g(x)) as f′(g(x))g′(x). Products require u′v+uv′.','链式法则为f′(g(x))g′(x)；乘积需u′v+uv′。','For y=(3x+1)², chain rule gives y′=2(3x+1)×3. At x=1 this is 24.','y=(3x+1)²求导得2(3x+1)×3，x=1时为24。','Trigonometric derivative rules require radians. A quotient rule requires a nonzero denominator.','三角求导规则要求弧度，商法则要求分母非零。',['Find y′ at x=1 for y=(3x+1)².','y=(3x+1)²在x=1处导数多少？',24],['Find it at x=0.','x=0处呢？',6,'2×1×3=6.','2×1×3=6。']);
R('M07.04','中值定理与形状','mean value theorem;monotonicity;concavity','中值定理;单调性;凹凸性','A continuous function on [a,b], differentiable inside, has some tangent slope equal to its secant slope. The second derivative describes changing slope.','闭区间连续且内部可导的函数，某处切线斜率等于割线斜率；二阶导数描述斜率变化。','For x² on [1,3], secant slope=(9−1)/2=4. Since f′(x)=2x, the matching point is x=2.','x²在[1,3]割线斜率4；导数2x，因此匹配点x=2。','A zero derivative alone does not prove an extremum; x³ has one at zero without turning.','导数为零不必是极值，x³在零处不会转向。',['Find the secant slope for x² on [1,3].','x²在[1,3]的割线斜率多少？',4],['Find the matching interior point.','匹配的内部点是多少？',2]);
R('M07.05','最优化与相关变化率','critical point;constraint;implicit differentiation','临界点;约束;隐式求导','Optimization compares critical points and boundary values. Related rates differentiate an equation connecting quantities changing with time.','优化须比较临界点与边界；相关变化率对随时间变化量之间的关系式求导。','A rectangle with perimeter 20 has area A=x(10−x). A′=10−2x vanishes at x=5, giving maximum area 25.','周长20的矩形面积为x(10−x)，导数10−2x在5为零，最大面积25。','State the physical domain: here 0≤x≤10. A stationary point outside it is irrelevant.','须说明实际定义域，此处0≤x≤10，范围外驻点无关。',['Find the maximizing x.','使面积最大时x多少？',5],['Find that maximum area.','最大面积多少？',25]);
R('M07.06','局部近似与误差','linearization;differential;error order','线性化;微分;误差阶','Near a, f(a+h)≈f(a)+f′(a)h. A bounded second derivative provides an error bound proportional to h².','a附近f(a+h)≈f(a)+f′(a)h；二阶导数有界时误差可由常数乘h²控制。','For √x near 4, f(4)=2 and f′(4)=1/4. Thus √4.04≈2+0.04/4=2.01.','√x在4附近，函数值2、导数1/4，所以√4.04≈2.01。','Approximation is not equality. Moving far from the expansion point may destroy accuracy.','近似不是相等，离展开点太远可能失准。',['Give the linear estimate of √4.04.','给出√4.04的线性估计。',2.01],['Give the linear estimate of √3.96.','给出√3.96的线性估计。',1.99,'2−0.04/4=1.99.','2−0.04/4=1.99。']);
F('M08','Integral calculus accumulates continuously varying quantities. A definite integral is a limit of weighted sums over a specified interval; it has units equal to the integrand units multiplied by the variable units. Signed area differs from total geometric area when the function is negative. The fundamental theorem connects accumulation to differentiation, but its hypotheses must be checked at discontinuities or unbounded endpoints. Antiderivatives differ by constants, while definite integrals give numbers. Infinite sums and improper integrals introduce another limit problem: terms must be combined through a defined limiting process, not manipulated as though infinitely many finite operations were automatically justified.','积分累积连续变化量。定积分是指定区间上加权和的极限，单位为被积函数单位乘变量单位。函数为负时，有向面积不同于几何总面积。微积分基本定理连接累积与求导，但在不连续或无界端点须检查条件。原函数相差常数，定积分给数值。无穷和与反常积分还引入极限问题，不能未经论证把无限操作当作有限代数。','calculus');
R('M08.01','黎曼和与定积分','partition;Riemann sum;signed area','分割;黎曼和;有向面积','A Riemann sum adds function height times interval width. Riemann integrability requires a common limit as the partition mesh tends to zero.','黎曼和累加函数高度乘小段宽度；黎曼可积要求分割网格趋零时有共同极限。','For f(x)=x on [0,2], triangular area is base 2 times height 2 divided by 2, giving integral 2.','f(x)=x在[0,2]下方为底2高2的三角形，积分为2。','Finite left and right sums are usually approximations.','有限左右和通常是近似。',['Find ∫₀² x dx.','求∫₀² x dx。',2],['Find ∫₀² 3 dx.','求∫₀² 3 dx。',6,'Constant height 3 times width 2 gives 6.','高3宽2的矩形面积6。']);
R('M08.02','微积分基本定理','accumulation;antiderivative;endpoint evaluation','累积;原函数;端点求值','For continuous f, F(x)=∫ₐˣf(t)dt has derivative f(x). If G′=f, then ∫ₐᵇf=G(b)−G(a).','f连续时F(x)=∫ₐˣf(t)dt满足F′=f；G′=f时定积分等于G(b)−G(a)。','An antiderivative of 2x is x². Therefore ∫₁³2x dx=9−1=8.','2x的原函数为x²，所以∫₁³2x dx=9−1=8。','Differentiate your proposed antiderivative before using the endpoint formula.','使用端点公式前先求导检验原函数。',['Find ∫₁³2x dx.','求∫₁³2x dx。',8],['For F(x)=∫₀ˣ2t dt, find F′(4).','F(x)=∫₀ˣ2t dt，求F′(4)。',8,'The derivative is 2x, giving 8.','导数为2x，代入得8。']);
R('M08.03','积分技巧','substitution;integration by parts;partial fractions','换元;分部积分;部分分式','Substitution reverses the chain rule. Integration by parts reverses the product rule: ∫u dv=uv−∫v du.','换元逆用链式法则；分部积分逆用乘积法则：∫u dv=uv−∫v du。','In ∫₀¹2x(x²+1)dx, set u=x²+1, du=2x dx. Bounds become 1,2, giving [u²/2]₁²=3/2.','∫₀¹2x(x²+1)dx令u=x²+1，du=2x dx，界限1、2，结果3/2。','Change bounds or return fully to the original variable; never mix both systems.','须变界限或完整换回原变量，不能混用。',['Evaluate the worked integral.','计算例中的积分。',1.5],['What u-bound corresponds to x=1?','x=1对应u上界多少？',2]);
R('M08.04','反常积分与应用','improper endpoint;convergence;comparison','反常端点;收敛;比较','An improper integral is defined by a limit at infinity or a singularity. Both sides of an interior singularity must converge separately.','反常积分用无穷或奇点处极限定义；内部奇点两侧须分别收敛。','∫₁ᴿx⁻²dx=1−1/R tends to 1. In contrast ∫₁ᴿ1/x dx=log R grows without bound.','∫₁ᴿx⁻²dx=1−1/R趋1，而∫₁ᴿ1/x dx=log R无界。','Cancellation across a singularity is not ordinary improper convergence.','奇点两边相消不等于普通反常积分收敛。',['Find ∫₁∞x⁻²dx.','求∫₁∞x⁻²dx。',1],['Find ∫₁²x⁻²dx.','求∫₁²x⁻²dx。',0.5,'1−1/2=1/2.','1−1/2=1/2。']);
R('M08.05','无穷级数与收敛','partial sums;geometric series;convergence tests','部分和;等比级数;收敛判别','A series converges when its partial sums converge. Terms tending to zero are necessary but insufficient; the harmonic series is a counterexample.','级数收敛指部分和收敛；通项趋零必要但不充分，调和级数是反例。','For |r|<1, (1−r^(n+1))/(1−r) tends to 1/(1−r). Thus 1+1/2+1/4+…=2.','|r|<1时有限等比和趋1/(1−r)，所以1+1/2+1/4+…=2。','The ratio test is inconclusive when its limiting ratio is 1.','比值判别极限为1时无法判断。',['Find Σ from n=0 of (1/2)^n.','求n从0开始的(1/2)^n无穷和。',2],['What if the sum starts at n=1?','从n=1开始呢？',1,'Remove the first term 1.','减去首项1。']);
R('M08.06','幂级数与泰勒近似','Taylor coefficient;radius;remainder','泰勒系数;收敛半径;余项','Taylor coefficients are f^(n)(a)/n!. Equality to an infinite Taylor series also requires the remainder to tend to zero.','泰勒系数为f^(n)(a)/n!；等于无穷泰勒级数还要求余项趋零。','The quadratic approximation to e^x at zero is 1+x+x²/2. At x=0.1 it gives 1.105, with nonzero higher-order error.','e^x在零的二次近似1+x+x²/2，在0.1处给1.105，仍有高阶误差。','Check convergence at boundary points separately.','收敛区间端点须单独检查。',['Give the quadratic estimate of e^0.1.','给e^0.1的二次估计。',1.105],['What is the x² coefficient?','x²系数多少？',0.5]);
F('M09','Linear algebra studies combinations formed by adding vectors and multiplying them by scalars. A linear map preserves these two operations, so knowing its action on a basis determines it everywhere. Matrices describe such maps after bases are chosen; changing a basis changes coordinates without changing the underlying map. Elimination exposes consistency, free variables, and pivot columns. Dimension counts independent directions, while determinants describe signed volume scaling for square maps. Eigenvectors identify directions that the map only scales. Always state the ambient vector space and scalar field, and distinguish the matrix shape from properties that require a square matrix.','线性代数研究向量相加和数乘组成的组合。线性映射保持这两种运算，因此知道基上的作用便确定全部作用。矩阵依选定的基描述映射，换基改变坐标却不改变映射本身。消元揭示相容性、自由变量和主元列。维数计独立方向，行列式描述方阵的有向体积缩放，特征向量给只被缩放的方向。须说明向量空间、数域和矩阵形状，方阵性质不能随意用于矩形矩阵。','linear');
R('M09.01','线性方程组与消元','row operation;pivot;free variable','行变换;主元;自由变量','Elementary row operations preserve the solution set: swap equations, scale by a nonzero number, or add a multiple of another equation.','交换方程、非零数乘方程或加另一方程倍数，都保持解集。','From x+y=5 and x−y=1, addition gives 2x=6, hence x=3 and y=2.','x+y=5与x−y=1相加得2x=6，所以x=3、y=2。','A row 0=1 signals inconsistency; a zero row alone does not imply a unique solution.','0=1表示不相容，零行本身不表示唯一解。',['Find x in the worked system.','求例中方程组x。',3],['Find y.','求y。',2]);
R('M09.02','向量、张成与无关性','span;linear dependence;homogeneous system','张成;线性相关;齐次方程组','A span is all linear combinations. Vectors are independent when the zero combination forces every coefficient to zero.','张成是全部线性组合；零组合只有全零系数时，向量组线性无关。','(1,0),(0,1) span the plane: (3,4)=3(1,0)+4(0,1). But (2,0) adds no new direction to (1,0).','(1,0)、(0,1)张成平面，(3,4)=3(1,0)+4(0,1)；(2,0)不增加新方向。','Independence concerns the whole collection, not merely unequal vector values.','无关性针对整个向量组，不是向量两两不相等。',['What coefficient multiplies (1,0) to represent (3,4)?','表示(3,4)时(1,0)系数多少？',3],['What is the dimension of span{(1,0),(2,0)}?','span{(1,0),(2,0)}维数多少？',1,'Both lie on the same one-dimensional axis.','二者都在同一条一维轴上。']);
R('M09.03','向量空间、基与维数','subspace;basis;dimension','子空间;基;维数','A subspace contains zero and is closed under addition and scalar multiplication. A basis is an independent spanning set; dimension is its size.','子空间含零且对加法数乘封闭。基是无关的生成集，维数为基的个数。','Polynomials of degree at most two have basis 1,x,x². A polynomial 2−3x+5x² has coordinates (2,−3,5) and the space has dimension 3.','至多二次多项式以1、x、x²为基；2−3x+5x²的坐标为(2,−3,5)，空间维数3。','Polynomials of exactly degree two do not form a subspace: zero is excluded.','恰好二次多项式不构成子空间，因为不含零。',['What is the dimension of polynomials of degree at most 2?','至多二次多项式空间维数多少？',3],['What is the x coefficient of 2−3x+5x²?','2−3x+5x²中x系数多少？',-3]);
R('M09.04','线性映射与矩阵','linearity;matrix columns;composition','线性;矩阵列;复合','A map is linear if T(au+bv)=aT(u)+bT(v). Matrix columns are images of the input basis vectors.','T(au+bv)=aT(u)+bT(v)定义线性；矩阵列就是输入基向量的像。','The diagonal matrix diag(2,3) maps (4,5) to (8,15). It stretches coordinate directions independently.','对角矩阵diag(2,3)把(4,5)映到(8,15)，分别拉伸两个坐标方向。','Adding a nonzero translation makes a map affine, not linear, because zero no longer maps to zero.','加非零平移会变为仿射而非线性，因为零不再映到零。',['Find the first coordinate of diag(2,3)(4,5).','diag(2,3)(4,5)首坐标多少？',8],['Find the second coordinate.','第二坐标多少？',15]);
R('M09.05','行列式与可逆性','determinant;inverse;volume scaling','行列式;逆;体积缩放','For a 2×2 matrix, determinant is ad−bc. A square matrix is invertible exactly when its determinant is nonzero.','二阶行列式为ad−bc；方阵当且仅当行列式非零时可逆。','For rows (2,1),(1,3), determinant is 6−1=5. Its inverse is (1/5) times the matrix with rows (3,−1),(−1,2).','矩阵行(2,1)、(1,3)的行列式为5，逆为1/5乘行(3,−1)、(−1,2)的矩阵。','Determinant zero means some direction collapses; it does not mean every matrix entry is zero.','行列式零表示某方向塌缩，不表示每个元素为零。',['Find that determinant.','求该行列式。',5],['Find the determinant of diag(2,4,3).','diag(2,4,3)行列式多少？',24,'Multiply diagonal entries: 2×4×3=24.','对角元相乘2×4×3=24。']);
R('M09.06','特征值与对角化','eigenvector;eigenvalue;diagonalization','特征向量;特征值;对角化','Av=λv with v nonzero defines an eigenpair. A matrix is diagonalizable when an entire basis consists of eigenvectors.','Av=λv且v非零定义特征对；存在特征向量基时矩阵可对角化。','diag(2,5) scales the first axis by 2 and second by 5. Its third power is diag(8,125).','diag(2,5)把第一轴放大2倍，第二轴5倍；三次幂为diag(8,125)。','Repeated eigenvalues may lack enough independent eigenvectors; diagonalization is not automatic.','重特征值可能没有足够无关特征向量，不能自动对角化。',['Find the smaller eigenvalue of diag(2,5).','diag(2,5)较小特征值多少？',2],['Find the second diagonal entry of its cube.','其三次幂第二对角元多少？',125]);
F('M10','Once a vector space has an inner product, lengths and angles allow approximation problems to be formulated geometrically. Orthogonality separates independent contributions to squared length. Projection finds the nearest vector in a subspace by requiring the residual to be orthogonal to that subspace. Spectral decompositions reveal how a map stretches special directions, while singular values extend that idea to rectangular maps. Coordinate transformations can simplify a quadratic form without changing its geometric meaning. Distinguish exact algebraic rank from numerical rank estimated using a tolerance, since tiny singular values can magnify data errors even when a formal inverse exists.','赋予内积后，向量空间具有长度与角，近似问题可几何化。正交使平方长度分解；投影要求残差垂直子空间，从而找最近向量。谱分解揭示特殊方向的拉伸，奇异值将它扩展到矩形矩阵。换坐标可简化二次型而不改变几何意义。精确代数秩与按容差估计的数值秩须区分：即使形式上可逆，极小奇异值也会放大数据误差。','linear');
R('M10.01','内积与正交','inner product;norm;Gram-Schmidt','内积;范数;施密特正交化','An inner product defines squared length ⟨v,v⟩. Gram-Schmidt subtracts projections onto earlier orthonormal directions.','内积给平方长度⟨v,v⟩；施密特过程减去前面正交归一方向上的投影。','From (1,0),(1,1), normalize the first vector, subtract its projection from the second, and obtain (0,1).','从(1,0)、(1,1)出发，先归一第一向量，再从第二向量减去投影，得到(0,1)。','An inner product must be positive definite; an arbitrary bilinear expression may not be one.','内积必须正定，任意双线性表达式未必是内积。',['Find (1,0)·(0,1).','求(1,0)·(0,1)。',0],['Find the norm of (0,1).','(0,1)范数多少？',1]);
R('M10.02','最小二乘与投影','normal equations;residual;orthogonal projection','正规方程;残差;正交投影','Least squares minimizes ||Ax−b||². Its residual is orthogonal to the column space, giving AᵀAx=Aᵀb.','最小二乘最小化||Ax−b||²；残差垂直列空间，因此AᵀAx=Aᵀb。','Project b=(3,4) onto the x-axis: the closest point is (3,0), residual (0,4), squared error 16.','把(3,4)投影到x轴，最近点(3,0)，残差(0,4)，平方误差16。','Normal equations can worsen numerical conditioning; QR or SVD is often preferable computationally.','正规方程可能恶化数值条件，计算常优先QR或SVD。',['Find the projection x-coordinate.','投影的x坐标多少？',3],['Find squared residual length.','残差平方长度多少？',16]);
R('M10.03','谱定理','symmetric matrix;orthogonal eigenbasis;real spectrum','对称矩阵;正交特征基;实谱','Every real symmetric matrix admits an orthonormal eigenbasis and real eigenvalues: A=QΛQᵀ.','实对称矩阵有正交归一特征基和实特征值，A=QΛQᵀ。','The matrix with rows (2,1),(1,2) has eigenvectors (1,1),(1,−1), with eigenvalues 3 and 1. Normalizing divides each vector by √2.','行(2,1)、(1,2)的矩阵对(1,1)、(1,−1)特征值为3、1，各除√2即可归一。','The real symmetric hypothesis matters; arbitrary real matrices may have complex eigenvalues.','实对称条件重要，一般实矩阵可能有复特征值。',['Find the larger eigenvalue.','较大特征值多少？',3],['Find the smaller eigenvalue.','较小特征值多少？',1]);
R('M10.04','奇异值分解','singular value;left vectors;rank approximation','奇异值;左奇异向量;低秩近似','SVD writes A=UΣVᵀ with orthonormal direction systems. Singular values are nonnegative square roots of eigenvalues of AᵀA.','SVD为A=UΣVᵀ，方向系正交归一；奇异值为AᵀA特征值的非负平方根。','For diag(3,−2), AᵀA=diag(9,4), so singular values are 3 and 2; signs are absorbed by direction vectors.','diag(3,−2)的AᵀA为diag(9,4)，奇异值3与2，符号由方向向量吸收。','Singular values are not generally eigenvalues; they remain meaningful for rectangular matrices.','奇异值通常不等于特征值，矩形矩阵也有奇异值。',['Find the largest singular value of diag(3,−2).','diag(3,−2)最大奇异值多少？',3],['Find the smallest.','最小奇异值多少？',2]);
R('M10.05','二次型与正定性','quadratic form;positive definite;Hessian','二次型;正定;海森矩阵','A symmetric quadratic form xᵀAx is positive definite when it is positive for every nonzero x, equivalently all eigenvalues are positive.','对称二次型xᵀAx对所有非零x为正时正定，等价于所有特征值正。','For A=diag(2,5), q(x,y)=2x²+5y². At (1,2), q=2+20=22, and every nonzero pair gives a positive result.','A=diag(2,5)时q=2x²+5y²，在(1,2)为22，任何非零对都为正。','Positive diagonal entries alone do not ensure positive definiteness when off-diagonal terms exist.','有非对角项时，仅对角元为正不能保证正定。',['Evaluate q at (1,2).','求q(1,2)。',22],['What is the minimum eigenvalue of this A?','此A最小特征值多少？',2]);
R('M10.06','标准形与应用','similarity;Jordan block;minimal polynomial','相似;约旦块;最小多项式','Similarity P⁻¹AP changes basis. Over the complex numbers, Jordan form records eigenvalues and any failure of diagonalizability through blocks.','相似变换P⁻¹AP表示换基；复数域上的约旦形用块记录特征值及不可对角化程度。','J=[[2,1],[0,2]]=2I+N with N²=0. Thus J²=4I+4N=[[4,4],[0,4]], despite having only one independent eigenvector.','J=[[2,1],[0,2]]=2I+N且N²=0，所以J²=[[4,4],[0,4]]，它仅有一个独立特征向量。','Similarity preserves eigenvalues but is different from changing a bilinear form by congruence.','相似保持特征值，但不同于二次型的合同变换。',['Find the upper-right entry of J².','J²右上元多少？',4],['How many independent eigenvectors does J have?','J有几个独立特征向量？',1]);
